package org.example.truepay.model;

public enum PaymentStatus {
    CREATED,
    VALIDATED,
    SENT,
    COMPLETED,
    FAILED
}

package org.example.truepay.model;

public enum PaymentStatus {
    PENDING,
    SUCCESS,
    FAILED,
    CANCELLED
}

package org.example.truepay.service;

import org.example.truepay.api.BankPaymentRequest;
import org.example.truepay.api.DashboardSummaryResponse;
import org.example.truepay.api.ReceiverVerificationResponse;
import org.example.truepay.api.TransactionAuditResponse;
import org.example.truepay.api.UpiPaymentRequest;
import org.example.truepay.model.*;
import org.example.truepay.repository.BankAccountRepository;
import org.example.truepay.repository.FraudAlertRepository;
import org.example.truepay.repository.PaymentRepository;
import org.example.truepay.repository.PaymentStatusHistoryRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;

@Service
public class PaymentService {
    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP", "INR");
    private static final BigDecimal MAX_AMOUNT = new BigDecimal("1000000.00");
    private static final BigDecimal FRAUD_AMOUNT = new BigDecimal("50000.00");

    private final PaymentRepository paymentRepository;
    private final PaymentStatusHistoryRepository statusHistoryRepository;
    private final FraudAlertRepository fraudAlertRepository;
    private final BankAccountRepository bankAccountRepository;
    private final ProfileService profileService;
    private final BankAccountService bankAccountService;
    private final BeneficiaryService beneficiaryService;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentStatusHistoryRepository statusHistoryRepository,
                          FraudAlertRepository fraudAlertRepository,
                          BankAccountRepository bankAccountRepository,
                          ProfileService profileService,
                          BankAccountService bankAccountService,
                          BeneficiaryService beneficiaryService) {
        this.paymentRepository = paymentRepository;
        this.statusHistoryRepository = statusHistoryRepository;
        this.fraudAlertRepository = fraudAlertRepository;
        this.bankAccountRepository = bankAccountRepository;
        this.profileService = profileService;
        this.bankAccountService = bankAccountService;
        this.beneficiaryService = beneficiaryService;
    }

    @Transactional
    public Payment createUpiPayment(Long userId, UpiPaymentRequest request) {
        return createAndProcessPayment(
                userId,
                request.sourceAccountId(),
                request.amount(),
                request.currency(),
                request.idempotencyKey(),
                request.bankPin(),
                PaymentMethod.UPI,
                request.destinationUpiId(),
                null,
                null,
                null,
                null
        );
    }

    @Transactional
    public Payment createBankPayment(Long userId, BankPaymentRequest request) {
        Beneficiary beneficiary = null;
        if (request.beneficiaryId() != null) {
            beneficiary = beneficiaryService.getOwnedOrThrow(userId, request.beneficiaryId());
        }

        String destinationAccount = beneficiary != null ? beneficiary.getAccountNumber() : request.destinationAccount();
        String destinationIfsc = beneficiary != null ? beneficiary.getIfscCode() : request.destinationIfsc();
        String receiverName = beneficiary != null ? beneficiary.getName() : request.receiverName();

        return createAndProcessPayment(
                userId,
                request.sourceAccountId(),
                request.amount(),
                request.currency(),
                request.idempotencyKey(),
                request.bankPin(),
                PaymentMethod.BANK,
                null,
                receiverName,
                destinationAccount,
                destinationIfsc,
                request.reference()
        );
    }

    private Payment createAndProcessPayment(Long userId,
                                            Long sourceAccountId,
                                            BigDecimal amount,
                                            String currency,
                                            String idempotencyKey,
                                            String bankPin,
                                            PaymentMethod method,
                                            String destinationUpi,
                                            String receiverName,
                                            String destinationAccount,
                                            String destinationIfsc,
                                            String referenceRemark) {

        Payment existing = paymentRepository.findByUserIdAndIdempotencyKey(userId, idempotencyKey).orElse(null);
        if (existing != null) {
            return existing;
        }

        UserProfile user = profileService.getUserOrThrow(userId);
        BankAccount source = bankAccountService.getForPayment(userId, sourceAccountId);
        bankAccountService.validateBankPin(source, bankPin);

        validatePaymentFields(source, amount, currency, method, destinationUpi, receiverName, destinationAccount, destinationIfsc);

        Payment payment = new Payment();
        payment.setUser(user);
        payment.setSourceAccount(source);
        payment.setMethod(method);
        payment.setAmount(amount);
        payment.setCurrency(currency.toUpperCase());
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDestinationUpiId(destinationUpi);
        payment.setReceiverName(receiverName);
        payment.setDestinationAccount(destinationAccount);
        payment.setDestinationIfsc(destinationIfsc != null ? destinationIfsc.toUpperCase(Locale.ROOT) : null);
        payment.setReferenceRemark(referenceRemark);
        payment.setStatus(PaymentStatus.CREATED);
        paymentRepository.save(payment);
        recordStatus(payment, PaymentStatus.CREATED, "API", "Payment submitted");

        payment.setStatus(PaymentStatus.VALIDATED);
        recordStatus(payment, PaymentStatus.VALIDATED, "SYSTEM", "Validation checks passed");

        if (runFraudChecks(payment)) {
            return payment;
        }

        if (source.getBalance().compareTo(amount) < 0) {
            failPayment(payment, ErrorCode.INSUFFICIENT_FUNDS, "Insufficient funds in source account");
            return payment;
        }

        payment.setStatus(PaymentStatus.SENT);
        recordStatus(payment, PaymentStatus.SENT, "SYSTEM", "Payment sent to destination simulator");

        source.setBalance(source.getBalance().subtract(amount));
        creditReceiverIfInternal(method, destinationAccount, destinationIfsc, amount);
        payment.setStatus(PaymentStatus.COMPLETED);
        recordStatus(payment, PaymentStatus.COMPLETED, "SYSTEM", "Payment completed successfully");

        return paymentRepository.save(payment);
    }

    private void validatePaymentFields(BankAccount sourceAccount,
                                       BigDecimal amount,
                                       String currency,
                                       PaymentMethod method,
                                       String destinationUpi,
                                       String receiverName,
                                       String destinationAccount,
                                       String destinationIfsc) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0 || amount.compareTo(MAX_AMOUNT) > 0) {
            throw new TruePayException(ErrorCode.INVALID_AMOUNT, HttpStatus.BAD_REQUEST, "Amount must be > 0 and <= 1,000,000");
        }

        if (!SUPPORTED_CURRENCIES.contains(currency.toUpperCase())) {
            throw new TruePayException(ErrorCode.INVALID_CURRENCY, HttpStatus.BAD_REQUEST,
                    "Unsupported currency. Supported: " + SUPPORTED_CURRENCIES);
        }

        if (method == PaymentMethod.UPI && (destinationUpi == null || destinationUpi.isBlank())) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST, "Destination UPI ID is required");
        }

        if (method == PaymentMethod.BANK && (destinationAccount == null || destinationAccount.isBlank() ||
                destinationIfsc == null || destinationIfsc.isBlank())) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST,
                    "Destination account and IFSC are required");
        }

        if (method == PaymentMethod.BANK && (receiverName == null || receiverName.isBlank())) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST,
                    "Receiver name is required");
        }

        if (method == PaymentMethod.BANK && !destinationAccount.matches("^\\d{8,20}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Receiver account number is invalid");
        }

        if (method == PaymentMethod.BANK && !destinationIfsc.toUpperCase(Locale.ROOT).matches("^[A-Z]{4}0[A-Z0-9]{6}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Receiver IFSC format is invalid");
        }

        if (method == PaymentMethod.BANK && sourceAccount.getAccountNumber().equals(destinationAccount)
                && sourceAccount.getIfscCode().equalsIgnoreCase(destinationIfsc)) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST,
                    "Sender and receiver accounts must be different");
        }
    }

    private void creditReceiverIfInternal(PaymentMethod method,
                                          String destinationAccount,
                                          String destinationIfsc,
                                          BigDecimal amount) {
        if (method != PaymentMethod.BANK) {
            return;
        }

        bankAccountRepository.findByAccountNumberAndIfscCode(destinationAccount, destinationIfsc.toUpperCase(Locale.ROOT))
                .ifPresent(receiver -> receiver.setBalance(receiver.getBalance().add(amount)));
    }

    private boolean runFraudChecks(Payment payment) {
        long recentPayments = paymentRepository.countByUserIdAndCreatedAtAfter(
                payment.getUser().getId(),
                Instant.now().minus(1, ChronoUnit.MINUTES)
        );

        boolean suspiciousAmount = payment.getAmount().compareTo(FRAUD_AMOUNT) > 0;
        boolean suspiciousFrequency = recentPayments > 3;

        if (suspiciousAmount || suspiciousFrequency) {
            FraudAlert alert = new FraudAlert();
            alert.setPayment(payment);
            alert.setRiskScore(suspiciousAmount ? 90 : 75);
            alert.setReason(suspiciousAmount
                    ? "High-value transaction detected"
                    : "Unusual transaction frequency detected");
            fraudAlertRepository.save(alert);

            failPayment(payment, ErrorCode.SUSPICIOUS_TRANSACTION, alert.getReason());
            return true;
        }

        return false;
    }

    private void failPayment(Payment payment, ErrorCode errorCode, String message) {
        payment.setStatus(PaymentStatus.FAILED);
        payment.setErrorCode(errorCode);
        payment.setErrorMessage(message);
        recordStatus(payment, PaymentStatus.FAILED, "SYSTEM", message);
        paymentRepository.save(payment);
    }

    private void recordStatus(Payment payment, PaymentStatus status, String actor, String notes) {
        payment.setStatus(status);

        PaymentStatusHistory history = new PaymentStatusHistory();
        history.setPayment(payment);
        history.setStatus(status);
        history.setTriggeredBy(actor);
        history.setNotes(notes);

        statusHistoryRepository.save(history);
    }

    public Payment getPayment(Long userId, UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new TruePayException(ErrorCode.PAYMENT_NOT_FOUND, HttpStatus.NOT_FOUND, "Payment not found"));
        if (!payment.getUser().getId().equals(userId)) {
            throw new TruePayException(ErrorCode.PAYMENT_NOT_FOUND, HttpStatus.NOT_FOUND, "Payment not found");
        }
        return payment;
    }

    public List<Payment> listPayments(Long userId, PaymentStatus status) {
        if (status == null) {
            return paymentRepository.findByUserIdOrderByCreatedAtDesc(userId);
        }
        return paymentRepository.findByUserIdAndStatusOrderByCreatedAtDesc(userId, status);
    }

    public List<PaymentStatusHistory> getHistory(Long userId, UUID paymentId) {
        getPayment(userId, paymentId);
        return statusHistoryRepository.findByPaymentIdOrderByChangedAtAsc(paymentId);
    }

    @Transactional(readOnly = true)
    public List<TransactionAuditResponse> getAuditHistory(Long userId) {
        return statusHistoryRepository.findAuditHistoryByUserIdOrderByChangedAtDesc(userId).stream()
                .map(history -> {
                    Payment payment = history.getPayment();
                    return new TransactionAuditResponse(
                            payment.getId(),
                            payment.getMethod(),
                            payment.getAmount(),
                            payment.getCurrency(),
                            resolveReceiver(payment),
                            history.getStatus(),
                            history.getTriggeredBy(),
                            history.getChangedAt(),
                            history.getNotes(),
                            payment.getReferenceRemark()
                    );
                })
                .toList();
    }

    public DashboardSummaryResponse getDashboardSummary(Long userId) {
        return new DashboardSummaryResponse(
                bankAccountService.combinedBalance(userId),
                bankAccountService.listForUser(userId).size(),
                paymentRepository.countByUserId(userId),
                paymentRepository.countByUserIdAndStatus(userId, PaymentStatus.COMPLETED),
                paymentRepository.countByUserIdAndStatus(userId, PaymentStatus.FAILED),
                fraudAlertRepository.countByPaymentUserId(userId)
        );
    }

    public ReceiverVerificationResponse verifyReceiver(String accountNumber, String ifscCode) {
        if (!accountNumber.matches("^\\d{8,12}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Account number must be 8-12 digits");
        }

        String normalizedIfsc = ifscCode.toUpperCase(Locale.ROOT);
        if (!normalizedIfsc.matches("^[A-Z]{4}0[A-Z0-9]{6}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Receiver IFSC format is invalid");
        }

        return bankAccountRepository.findByAccountNumberAndIfscCode(accountNumber, normalizedIfsc)
                .map(account -> new ReceiverVerificationResponse(true, account.getUser().getFullName(), "Receiver verified in TruePay"))
                .orElseGet(() -> new ReceiverVerificationResponse(false, "External account", "Receiver not found in TruePay, transfer will be simulated"));
    }

    private String resolveReceiver(Payment payment) {
        if (payment.getReceiverName() != null && !payment.getReceiverName().isBlank()) {
            return payment.getReceiverName();
        }
        if (payment.getDestinationUpiId() != null && !payment.getDestinationUpiId().isBlank()) {
            return payment.getDestinationUpiId();
        }
        if (payment.getDestinationAccount() != null && !payment.getDestinationAccount().isBlank()) {
            return payment.getDestinationAccount();
        }
        return "-";
    }
}

package org.example.truepay.service;

import org.example.truepay.api.BankPaymentRequest;
import org.example.truepay.api.DashboardSummaryResponse;
import org.example.truepay.api.ReceiverVerificationResponse;
import org.example.truepay.api.TransactionAuditResponse;
import org.example.truepay.api.UpiPaymentRequest;
import org.example.truepay.model.*;
import org.example.truepay.repository.BankAccountRepository;
import org.example.truepay.repository.FraudAlertRepository;
import org.example.truepay.repository.PaymentRepository;
import org.example.truepay.repository.PaymentStatusHistoryRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;

@Service
public class PaymentService {
    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP", "INR");
    private static final BigDecimal MAX_AMOUNT = new BigDecimal("1000000.00");
    private static final BigDecimal FRAUD_AMOUNT = new BigDecimal("50000.00");

    private final PaymentRepository paymentRepository;
    private final PaymentStatusHistoryRepository statusHistoryRepository;
    private final FraudAlertRepository fraudAlertRepository;
    private final BankAccountRepository bankAccountRepository;
    private final ProfileService profileService;
    private final BankAccountService bankAccountService;
    private final BeneficiaryService beneficiaryService;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentStatusHistoryRepository statusHistoryRepository,
                          FraudAlertRepository fraudAlertRepository,
                          BankAccountRepository bankAccountRepository,
                          ProfileService profileService,
                          BankAccountService bankAccountService,
                          BeneficiaryService beneficiaryService) {
        this.paymentRepository = paymentRepository;
        this.statusHistoryRepository = statusHistoryRepository;
        this.fraudAlertRepository = fraudAlertRepository;
        this.bankAccountRepository = bankAccountRepository;
        this.profileService = profileService;
        this.bankAccountService = bankAccountService;
        this.beneficiaryService = beneficiaryService;
    }

    @Transactional
    public Payment createUpiPayment(Long userId, UpiPaymentRequest request) {
        return createAndProcessPayment(
                userId,
                request.sourceAccountId(),
                request.amount(),
                request.currency(),
                request.idempotencyKey(),
                request.bankPin(),
                PaymentMethod.UPI,
                request.destinationUpiId(),
                null,
                null,
                null,
                null
        );
    }

    @Transactional
    public Payment createBankPayment(Long userId, BankPaymentRequest request) {
        Beneficiary beneficiary = null;
        if (request.beneficiaryId() != null) {
            beneficiary = beneficiaryService.getOwnedOrThrow(userId, request.beneficiaryId());
        }

        String destinationAccount = beneficiary != null ? beneficiary.getAccountNumber() : request.destinationAccount();
        String destinationIfsc = beneficiary != null ? beneficiary.getIfscCode() : request.destinationIfsc();
        String receiverName = beneficiary != null ? beneficiary.getName() : request.receiverName();

        return createAndProcessPayment(
                userId,
                request.sourceAccountId(),
                request.amount(),
                request.currency(),
                request.idempotencyKey(),
                request.bankPin(),
                PaymentMethod.BANK,
                null,
                receiverName,
                destinationAccount,
                destinationIfsc,
                request.reference()
        );
    }

    private Payment createAndProcessPayment(Long userId,
                                            Long sourceAccountId,
                                            BigDecimal amount,
                                            String currency,
                                            String idempotencyKey,
                                            String bankPin,
                                            PaymentMethod method,
                                            String destinationUpi,
                                            String receiverName,
                                            String destinationAccount,
                                            String destinationIfsc,
                                            String referenceRemark) {

        Payment existing = paymentRepository.findByUserIdAndIdempotencyKey(userId, idempotencyKey).orElse(null);
        if (existing != null) {
            return existing;
        }

        UserProfile user = profileService.getUserOrThrow(userId);

        Payment payment = createPendingPayment(user, amount, currency, idempotencyKey, method,
                destinationUpi, receiverName, destinationAccount, destinationIfsc, referenceRemark);

        try {
            BankAccount source = bankAccountRepository.findByIdForUpdate(sourceAccountId).orElse(null);
            if (source == null || !source.getUser().getId().equals(userId)) {
                failPayment(payment, ErrorCode.INVALID_ACCOUNT, "Source account not found");
                return payment;
            }

            payment.setSourceAccount(source);
            paymentRepository.save(payment);

            bankAccountService.validateBankPin(source, bankPin);
            validatePaymentFields(source, amount, currency, method, destinationUpi, receiverName, destinationAccount, destinationIfsc);

            if (runFraudChecks(payment)) {
                return payment;
            }

            if (source.getBalance().compareTo(amount) < 0) {
                failPayment(payment, ErrorCode.INSUFFICIENT_FUNDS, "Insufficient balance");
                return payment;
            }

            Optional<BankAccount> destination = findDestinationAccount(method, destinationAccount, destinationIfsc);
            if (method == PaymentMethod.BANK && destination.isEmpty()) {
                failPayment(payment, ErrorCode.INVALID_ACCOUNT, "Destination account not found");
                return payment;
            }

            source.setBalance(source.getBalance().subtract(amount));
            destination.ifPresent(receiver -> receiver.setBalance(receiver.getBalance().add(amount)));

            payment.setStatus(PaymentStatus.SUCCESS);
            payment.setErrorCode(null);
            payment.setErrorMessage(null);
            payment.setFailureReason(null);
            recordStatus(payment, PaymentStatus.SUCCESS, "SYSTEM", "Payment completed successfully");

            return paymentRepository.save(payment);
        } catch (TruePayException ex) {
            failPayment(payment, ex.getErrorCode(), ex.getMessage());
            return payment;
        } catch (Exception ex) {
            failPayment(payment, ErrorCode.PROCESSING_ERROR, ex.getMessage());
            return payment;
        }
    }

    private Payment createPendingPayment(UserProfile user,
                                         BigDecimal amount,
                                         String currency,
                                         String idempotencyKey,
                                         PaymentMethod method,
                                         String destinationUpi,
                                         String receiverName,
                                         String destinationAccount,
                                         String destinationIfsc,
                                         String referenceRemark) {
        Payment payment = new Payment();
        payment.setUser(user);
        payment.setMethod(method);
        payment.setAmount(amount);
        payment.setCurrency(currency != null ? currency.toUpperCase(Locale.ROOT) : null);
        payment.setIdempotencyKey(idempotencyKey);
        payment.setDestinationUpiId(destinationUpi);
        payment.setReceiverName(receiverName);
        payment.setDestinationAccount(destinationAccount);
        payment.setDestinationIfsc(destinationIfsc != null ? destinationIfsc.toUpperCase(Locale.ROOT) : null);
        payment.setReferenceRemark(referenceRemark);
        payment.setStatus(PaymentStatus.PENDING);
        paymentRepository.save(payment);
        recordStatus(payment, PaymentStatus.PENDING, "API", "Payment submitted");
        return payment;
    }

    private void validatePaymentFields(BankAccount sourceAccount,
                                       BigDecimal amount,
                                       String currency,
                                       PaymentMethod method,
                                       String destinationUpi,
                                       String receiverName,
                                       String destinationAccount,
                                       String destinationIfsc) {
        if (amount.compareTo(BigDecimal.ZERO) <= 0 || amount.compareTo(MAX_AMOUNT) > 0) {
            throw new TruePayException(ErrorCode.INVALID_AMOUNT, HttpStatus.BAD_REQUEST, "Invalid payment amount");
        }

        if (!SUPPORTED_CURRENCIES.contains(currency.toUpperCase())) {
            throw new TruePayException(ErrorCode.INVALID_CURRENCY, HttpStatus.BAD_REQUEST,
                    "Unsupported currency. Supported: " + SUPPORTED_CURRENCIES);
        }

        if (method == PaymentMethod.UPI && (destinationUpi == null || destinationUpi.isBlank())) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST, "Destination UPI ID is required");
        }

        if (method == PaymentMethod.BANK && (destinationAccount == null || destinationAccount.isBlank() ||
                destinationIfsc == null || destinationIfsc.isBlank())) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST,
                    "Destination account and IFSC are required");
        }

        if (method == PaymentMethod.BANK && (receiverName == null || receiverName.isBlank())) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST,
                    "Receiver name is required");
        }

        if (method == PaymentMethod.BANK && !destinationAccount.matches("^\\d{8,20}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Receiver account number is invalid");
        }

        if (method == PaymentMethod.BANK && !destinationIfsc.toUpperCase(Locale.ROOT).matches("^[A-Z]{4}0[A-Z0-9]{6}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Receiver IFSC format is invalid");
        }

        if (method == PaymentMethod.BANK && sourceAccount.getAccountNumber().equals(destinationAccount)
                && sourceAccount.getIfscCode().equalsIgnoreCase(destinationIfsc)) {
            throw new TruePayException(ErrorCode.VALIDATION_FAILED, HttpStatus.BAD_REQUEST,
                    "Sender and receiver accounts must be different");
        }
    }

    private Optional<BankAccount> findDestinationAccount(PaymentMethod method,
                                                         String destinationAccount,
                                                         String destinationIfsc) {
        if (method != PaymentMethod.BANK) {
            return Optional.empty();
        }
        return bankAccountRepository.findByAccountNumberAndIfscCode(destinationAccount, destinationIfsc.toUpperCase(Locale.ROOT));
    }

    private boolean runFraudChecks(Payment payment) {
        long recentPayments = paymentRepository.countByUserIdAndCreatedAtAfter(
                payment.getUser().getId(),
                Instant.now().minus(1, ChronoUnit.MINUTES)
        );

        boolean suspiciousAmount = payment.getAmount().compareTo(FRAUD_AMOUNT) > 0;
        boolean suspiciousFrequency = recentPayments > 3;

        if (suspiciousAmount || suspiciousFrequency) {
            FraudAlert alert = new FraudAlert();
            alert.setPayment(payment);
            alert.setRiskScore(suspiciousAmount ? 90 : 75);
            alert.setReason(suspiciousAmount
                    ? "High-value transaction detected"
                    : "Unusual transaction frequency detected");
            fraudAlertRepository.save(alert);

            failPayment(payment, ErrorCode.SUSPICIOUS_TRANSACTION, alert.getReason());
            return true;
        }

        return false;
    }

    private void failPayment(Payment payment, ErrorCode errorCode, String message) {
        payment.setStatus(PaymentStatus.FAILED);
        payment.setErrorCode(errorCode);
        payment.setErrorMessage(message);
        payment.setFailureReason(message);
        recordStatus(payment, PaymentStatus.FAILED, "SYSTEM", message);
        paymentRepository.save(payment);
    }

    @Transactional
    public Payment cancelPayment(Long userId, UUID paymentId, String reason) {
        Payment payment = getPayment(userId, paymentId);
        if (payment.getStatus() != PaymentStatus.PENDING) {
            throw new TruePayException(ErrorCode.INVALID_STATUS_TRANSITION, HttpStatus.CONFLICT,
                    "Only pending transactions can be cancelled");
        }

        String cancellationReason = (reason == null || reason.isBlank()) ? "Cancelled by user" : reason.trim();
        payment.setStatus(PaymentStatus.CANCELLED);
        payment.setFailureReason(cancellationReason);
        payment.setErrorCode(null);
        payment.setErrorMessage(cancellationReason);
        recordStatus(payment, PaymentStatus.CANCELLED, "USER", cancellationReason);
        return paymentRepository.save(payment);
    }

    private void recordStatus(Payment payment, PaymentStatus status, String actor, String notes) {
        payment.setStatus(status);

        PaymentStatusHistory history = new PaymentStatusHistory();
        history.setPayment(payment);
        history.setStatus(status);
        history.setTriggeredBy(actor);
        history.setNotes(notes);

        statusHistoryRepository.save(history);
    }

    public Payment getPayment(Long userId, UUID paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new TruePayException(ErrorCode.PAYMENT_NOT_FOUND, HttpStatus.NOT_FOUND, "Payment not found"));
        if (!payment.getUser().getId().equals(userId)) {
            throw new TruePayException(ErrorCode.PAYMENT_NOT_FOUND, HttpStatus.NOT_FOUND, "Payment not found");
        }
        return payment;
    }

    public List<Payment> listPayments(Long userId, PaymentStatus status) {
        if (status == null) {
            return paymentRepository.findByUserIdOrderByCreatedAtDesc(userId);
        }
        return paymentRepository.findByUserIdAndStatusOrderByCreatedAtDesc(userId, status);
    }

    public List<PaymentStatusHistory> getHistory(Long userId, UUID paymentId) {
        getPayment(userId, paymentId);
        return statusHistoryRepository.findByPaymentIdOrderByChangedAtAsc(paymentId);
    }

    @Transactional(readOnly = true)
    public List<TransactionAuditResponse> getAuditHistory(Long userId) {
        return statusHistoryRepository.findAuditHistoryByUserIdOrderByChangedAtDesc(userId).stream()
                .map(history -> {
                    Payment payment = history.getPayment();
                    return new TransactionAuditResponse(
                            payment.getId(),
                            payment.getMethod(),
                            payment.getAmount(),
                            payment.getCurrency(),
                            resolveReceiver(payment),
                            history.getStatus(),
                            history.getTriggeredBy(),
                            history.getChangedAt(),
                            history.getNotes(),
                            payment.getReferenceRemark()
                    );
                })
                .toList();
    }

    public DashboardSummaryResponse getDashboardSummary(Long userId) {
        return new DashboardSummaryResponse(
                bankAccountService.combinedBalance(userId),
                bankAccountService.listForUser(userId).size(),
                paymentRepository.countByUserId(userId),
                paymentRepository.countByUserIdAndStatus(userId, PaymentStatus.SUCCESS),
                paymentRepository.countByUserIdAndStatus(userId, PaymentStatus.FAILED),
                fraudAlertRepository.countByPaymentUserId(userId)
        );
    }

    public ReceiverVerificationResponse verifyReceiver(String accountNumber, String ifscCode) {
        if (!accountNumber.matches("^\\d{8,12}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Account number must be 8-12 digits");
        }

        String normalizedIfsc = ifscCode.toUpperCase(Locale.ROOT);
        if (!normalizedIfsc.matches("^[A-Z]{4}0[A-Z0-9]{6}$")) {
            throw new TruePayException(ErrorCode.INVALID_ACCOUNT, HttpStatus.BAD_REQUEST, "Receiver IFSC format is invalid");
        }

        return bankAccountRepository.findByAccountNumberAndIfscCode(accountNumber, normalizedIfsc)
                .map(account -> new ReceiverVerificationResponse(true, account.getUser().getFullName(), "Receiver verified in TruePay"))
                .orElseGet(() -> new ReceiverVerificationResponse(false, "External account", "Receiver not found in TruePay, transfer will be simulated"));
    }

    private String resolveReceiver(Payment payment) {
        if (payment.getReceiverName() != null && !payment.getReceiverName().isBlank()) {
            return payment.getReceiverName();
        }
        if (payment.getDestinationUpiId() != null && !payment.getDestinationUpiId().isBlank()) {
            return payment.getDestinationUpiId();
        }
        if (payment.getDestinationAccount() != null && !payment.getDestinationAccount().isBlank()) {
            return payment.getDestinationAccount();
        }
        return "-";
    }
}

/* TruePay dashboard frontend */
const state = { user: null, accounts: [], payments: [], audits: [], summary: null, charts: {} };

/* Theme */
function getTheme() {
  return localStorage.getItem('theme') || 'dark';
}

function applyTheme(theme) {
  const dark = theme === 'dark';
  document.body.classList.toggle('dark', dark);
  document.getElementById('themeSwitch').classList.toggle('on', dark);
}

function toggleTheme() {
  const next = getTheme() === 'dark' ? 'light' : 'dark';
  localStorage.setItem('theme', next);
  applyTheme(next);
}

/* Navigation */
function navigate(page) {
  document.querySelectorAll('.page').forEach((p) => p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach((n) => n.classList.remove('active'));

  const pageEl = document.getElementById('page-' + page);
  if (pageEl) pageEl.classList.add('active');

  const navEl = document.querySelector(`.nav-item[data-page="${page}"]`);
  if (navEl) navEl.classList.add('active');

  const titles = {
    dashboard: ['Dashboard', "Welcome back! Here's your overview."],
    history: ['Payment History', 'All your transactions in one place.'],
    audits: ['Audit History', 'Every transaction event, actor, and status change.'],
    'pay-upi': ['Pay to UPI', 'Send money instantly via UPI.'],
    'pay-bank': ['Bank Transfer', 'Transfer funds to any bank account.'],
    accounts: ['Bank Accounts', 'Manage your linked accounts.'],
    profile: ['Profile', 'Your personal information.']
  };

  const [title, sub] = titles[page] || ['TruePay', ''];
  document.getElementById('topbarTitle').textContent = title;
  document.getElementById('topbarSub').textContent = sub;
}

/* API */
async function api(path, options = {}) {
  const res = await fetch(path, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {})
    }
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || 'Request failed');
  }

  if (res.status === 204) return null;
  return res.json().catch(() => null);
}

/* Formatting */
function inr(v) {
  return 'INR ' + Number(v || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function maskNum(n) {
  return n ? '**** ' + n.slice(-4) : '-';
}

function fmtDate(d) {
  return d ? new Date(d).toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '-';
}

function statusIcon(s) {
  return { COMPLETED: 'OK', FAILED: 'X', CREATED: 'NEW', VALIDATED: 'CHK', SENT: 'SENT' }[s] || '...';
}

/* Render */
function renderSidebar() {
  if (!state.user) return;
  const sidebarName = document.getElementById('sidebarName');
  const sidebarEmail = document.getElementById('sidebarEmail');
  const sidebarAvatar = document.getElementById('sidebarAvatar');

  if (sidebarName) sidebarName.textContent = state.user.fullName;
  if (sidebarEmail) sidebarEmail.textContent = state.user.email;
  if (sidebarAvatar) sidebarAvatar.textContent = state.user.fullName.charAt(0).toUpperCase();
}

function renderKPIs() {
  if (!state.summary) return;
  const s = state.summary;
  document.getElementById('kpiBalance').textContent = inr(s.combinedBalance);
  document.getElementById('kpiAccounts').textContent = s.linkedBankAccounts + ' accounts linked';
  document.getElementById('kpiCompleted').textContent = s.completedPayments;
  document.getElementById('kpiFailed').textContent = s.failedPayments;
  document.getElementById('kpiFraud').textContent = s.fraudAlerts;
  document.getElementById('chartTotalLabel').textContent = s.totalPayments + ' total payments';
}

function renderCharts() {
  if (!state.summary) return;

  ['volumeChart', 'statusChart', 'methodChart', 'riskChart'].forEach((id) => {
    if (state.charts[id]) state.charts[id].destroy();
  });

  const s = state.summary;
  const completed = s.completedPayments;
  const failed = s.failedPayments;
  const inProgress = Math.max(0, s.totalPayments - completed - failed);

  const lastSeven = [0, 0, 0, 0, 0, 0, 0];
  const now = new Date();
  state.payments.forEach((p) => {
    const days = Math.floor((now - new Date(p.createdAt)) / 86400000);
    if (days >= 0 && days < 7) lastSeven[6 - days] += 1;
  });
  const labels = [...Array(7)].map((_, i) => {
    const d = new Date(now);
    d.setDate(d.getDate() - (6 - i));
    return (d.getMonth() + 1) + '/' + d.getDate();
  });

  state.charts.volumeChart = new Chart(document.getElementById('volumeChart'), {
    type: 'line',
    data: { labels, datasets: [{ label: 'Payments', data: lastSeven, borderColor: '#7c5cfc', tension: 0.35 }] },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1
          }
        }
      }
    }
  });

  state.charts.statusChart = new Chart(document.getElementById('statusChart'), {
    type: 'doughnut',
    data: { labels: ['Completed', 'Failed', 'In Progress'], datasets: [{ data: [completed, failed, inProgress], backgroundColor: ['#22c55e', '#ef4444', '#7c5cfc'] }] },
    options: { responsive: true, cutout: '65%', plugins: { legend: { display: false } } }
  });

  const upiCount = state.payments.filter((p) => p.method === 'UPI').length;
  const bankCount = state.payments.filter((p) => p.method === 'BANK').length;
  state.charts.methodChart = new Chart(document.getElementById('methodChart'), {
    type: 'bar',
    data: { labels: ['UPI', 'Bank Transfer'], datasets: [{ data: [upiCount, bankCount], backgroundColor: ['rgba(124,92,252,.8)', 'rgba(79,140,255,.8)'] }] },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1
          }
        }
      }
    }
  });

  state.charts.riskChart = new Chart(document.getElementById('riskChart'), {
    type: 'bar',
    data: { labels: ['Completed', 'Failed', 'Fraud Alerts'], datasets: [{ data: [completed, failed, s.fraudAlerts], backgroundColor: ['rgba(34,197,94,.7)', 'rgba(239,68,68,.7)', 'rgba(251,146,60,.7)'] }] },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1
          }
        }
      }
    }
  });

  const total = completed + failed + inProgress || 1;
  document.getElementById('distList').innerHTML = [
    { label: 'Completed', val: completed, color: '#22c55e' },
    { label: 'Failed', val: failed, color: '#ef4444' },
    { label: 'In Progress', val: inProgress, color: '#7c5cfc' }
  ].map((d) => `<div class="dist-item"><div class="dist-dot" style="background:${d.color}"></div><span class="dist-label">${d.label}</span><span class="dist-val">${d.val}</span><span class="dist-pct">${Math.round((d.val / total) * 100)}%</span></div>`).join('');
}

function renderHistory() {
  const filter = document.getElementById('historyFilter').value;
  const data = filter ? state.payments.filter((p) => p.status === filter) : state.payments;
  const tbody = document.getElementById('historyTableBody');

  if (!data.length) {
    tbody.innerHTML = '<tr><td colspan="7" class="empty">No payments found.</td></tr>';
    return;
  }

  tbody.innerHTML = data.slice(0, 50).map((p) => `
    <tr>
      <td style="font-family:monospace;font-size:11px;color:var(--text-sub);">${p.id.slice(0, 8)}...</td>
      <td><span class="tag tag-${p.method === 'UPI' ? 'upi' : 'bank'}">${p.method}</span></td>
      <td>${p.receiverName || p.destinationUpiId || '-'}</td>
      <td style="font-weight:700;">${p.amount} <span style="color:var(--text-sub);font-size:11px;">${p.currency}</span></td>
      <td><span class="status-badge ${p.status}">${statusIcon(p.status)} ${p.status}</span></td>
      <td style="color:var(--text-sub);">${fmtDate(p.createdAt)}</td>
      <td><button class="btn btn-secondary" style="padding:5px 10px;font-size:11px;" onclick="showPaymentDetail('${p.id}')">Detail</button></td>
    </tr>`).join('');
}

function renderAccounts() {
  document.getElementById('accCombined').textContent = state.summary ? inr(state.summary.combinedBalance) : 'INR 0.00';

  const html = state.accounts.map((a) => `
    <div class="account-chip">
      <div class="account-chip-icon">B</div>
      <div class="account-chip-info">
        <div class="account-chip-bank">${a.bankName}</div>
        <div class="account-chip-num">${maskNum(a.accountNumber)} | ${a.ifscCode}</div>
        <div style="font-size:11px;color:var(--text-sub);margin-top:2px;">${a.accountHolderName || ''} ${a.accountType ? '· <span class="tag" style="font-size:10px;padding:2px 6px;">' + a.accountType + '</span>' : ''}</div>
      </div>
      <div class="account-chip-bal">${inr(a.balance)}</div>
      <button class="btn btn-danger" onclick="deleteBankAccount(${a.id})">Delete</button>
    </div>`).join('');

  document.getElementById('accountsList').innerHTML = html || '<div class="empty">No bank accounts linked yet.</div>';
  document.getElementById('upiAccountPreview').innerHTML = html || '<div class="empty">No accounts.</div>';

  const options = state.accounts.map((a) => `<option value="${a.id}">${a.bankName} | ${maskNum(a.accountNumber)} (${inr(a.balance)})</option>`).join('');
  ['upiSource', 'bankSource'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = options;
  });

  const sideList = state.accounts.slice(0, 5).map((a) => `
    <div class="dashboard-account-item">
      <div>
        <div class="dashboard-account-bank">${a.bankName}</div>
        <div class="dashboard-account-num">${maskNum(a.accountNumber)}${a.accountType ? ' · ' + a.accountType : ''}</div>
      </div>
      <div class="dashboard-account-bal">${inr(a.balance)}</div>
    </div>`).join('');
  const dashboardAccounts = document.getElementById('dashboardBankAccountsList');
  if (dashboardAccounts) {
    dashboardAccounts.innerHTML = sideList || '<div class="empty">No linked accounts yet.</div>';
  }
}

function renderDashboardRecent() {
  const tbody = document.getElementById('dashboardRecentBody');
  if (!tbody) return;

  if (!state.payments.length) {
    tbody.innerHTML = '<tr><td colspan="4" class="empty">No recent transactions.</td></tr>';
    return;
  }

  tbody.innerHTML = state.payments.slice(0, 6).map((p) => `
    <tr>
      <td style="font-family:monospace;font-size:11px;color:var(--text-sub);">${p.id.slice(0, 8)}...</td>
      <td>${p.receiverName || p.destinationUpiId || '-'}</td>
      <td style="font-weight:700;">${p.amount} ${p.currency}</td>
      <td><span class="status-badge ${p.status}">${p.status}</span></td>
    </tr>`).join('');
}

function renderProfile() {
  if (!state.user) return;
  document.getElementById('profileContent').innerHTML = `
    <div class="account-chip" style="margin-bottom:12px;">
      <div class="sidebar-avatar">${state.user.fullName.charAt(0).toUpperCase()}</div>
      <div class="account-chip-info">
        <div class="account-chip-bank">${state.user.fullName}</div>
        <div class="account-chip-num">${state.user.email}</div>
      </div>
    </div>
    <div style="font-size:14px;display:flex;flex-direction:column;gap:10px;">
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">Full Name</span><strong>${state.user.fullName}</strong></div>
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">Email</span><strong>${state.user.email}</strong></div>
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">Mobile</span><strong>${state.user.mobile}</strong></div>
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">User ID</span><strong>#${state.user.id}</strong></div>
    </div>`;
}

function renderAudits() {
  const tbody = document.getElementById('auditTableBody');
  if (!tbody) return;

  const filter = document.getElementById('auditStatusFilter')?.value || '';
  const data = filter ? state.audits.filter((audit) => audit.status === filter) : state.audits;

  const eventCount = document.getElementById('auditEventCount');
  const transactionCount = document.getElementById('auditTransactionCount');
  const latestAt = document.getElementById('auditLatestAt');

  if (eventCount) eventCount.textContent = data.length;
  if (transactionCount) transactionCount.textContent = new Set(data.map((audit) => audit.paymentId)).size;
  if (latestAt) latestAt.textContent = data.length ? fmtDate(data[0].changedAt) : '-';

  if (!data.length) {
    tbody.innerHTML = '<tr><td colspan="9" class="empty">No audit events found.</td></tr>';
    return;
  }

  tbody.innerHTML = data.slice(0, 100).map((audit) => `
    <tr>
      <td style="color:var(--text-sub);">${fmtDate(audit.changedAt)}</td>
      <td style="font-family:monospace;font-size:11px;color:var(--text-sub);">${audit.paymentId.slice(0, 8)}...</td>
      <td><span class="tag tag-${audit.method === 'UPI' ? 'upi' : 'bank'}">${audit.method}</span></td>
      <td>${audit.receiver || '-'}</td>
      <td style="font-weight:700;">${audit.amount} <span style="color:var(--text-sub);font-size:11px;">${audit.currency}</span></td>
      <td><span class="status-badge ${audit.status}">${statusIcon(audit.status)} ${audit.status}</span></td>
      <td>${audit.triggeredBy}</td>
      <td>
        <div>${audit.notes || '-'}</div>
        ${audit.referenceRemark ? `<div class="audit-reference">Ref: ${audit.referenceRemark}</div>` : ''}
      </td>
      <td><button class="btn btn-secondary" style="padding:5px 10px;font-size:11px;" onclick="openAuditPayment('${audit.paymentId}')">Transaction</button></td>
    </tr>`).join('');
}

async function showPaymentDetail(paymentId) {
  const payment = state.payments.find((p) => p.id === paymentId);
  if (!payment) return;

  const content = document.getElementById('paymentDetailContent');
  content.innerHTML = `
    <div class="page-grid-2" style="margin-bottom:12px;">
      <div><div class="kpi-label">Payment ID</div><div style="font-family:monospace;font-size:12px;">${payment.id}</div></div>
      <div><div class="kpi-label">Status</div><span class="status-badge ${payment.status}">${statusIcon(payment.status)} ${payment.status}</span></div>
      <div><div class="kpi-label">Amount</div><div style="font-weight:700;">${payment.amount} ${payment.currency}</div></div>
      <div><div class="kpi-label">Method</div><span class="tag tag-${payment.method === 'UPI' ? 'upi' : 'bank'}">${payment.method}</span></div>
      <div><div class="kpi-label">Receiver</div><div>${payment.receiverName || payment.destinationUpiId || '-'}</div></div>
      <div><div class="kpi-label">Reference</div><div>${payment.referenceRemark || '-'}</div></div>
      <div><div class="kpi-label">Created</div><div style="color:var(--text-sub);">${fmtDate(payment.createdAt)}</div></div>
      ${payment.errorMessage ? `<div style="grid-column:1/-1;"><div class="kpi-label">Error</div><div style="color:var(--red);">${payment.errorMessage}</div></div>` : ''}
    </div>`;

  document.getElementById('paymentDetailPanel').style.display = 'block';

  try {
    const history = await api(`/api/v1/payments/${paymentId}/history`);
    document.getElementById('paymentTimeline').innerHTML = (history || []).map((h) => `
      <div class="timeline-item">
        <div class="timeline-dot ${h.status}">${statusIcon(h.status)}</div>
        <div class="timeline-content">
          <div class="timeline-label">${h.status}</div>
          <div class="timeline-time">${fmtDate(h.changedAt)} by ${h.triggeredBy}</div>
          <div class="timeline-note">${h.notes || ''}</div>
        </div>
      </div>`).join('');
  } catch (_) {
    document.getElementById('paymentTimeline').innerHTML = '';
  }
}

function openAuditPayment(paymentId) {
  navigate('history');
  showPaymentDetail(paymentId);
}

/* Actions */
async function deleteBankAccount(id) {
  if (!confirm('Delete this bank account? Only allowed with zero balance.')) return;
  try {
    await api(`/api/v1/bank-accounts/${id}`, { method: 'DELETE' });
    await loadAll();
  } catch (e) {
    alert(e.message);
  }
}

/* Form helpers */
function showResult(id, message, ok) {
  const el = document.getElementById(id);
  el.textContent = message;
  el.className = 'verify-result ' + (ok ? 'show-ok' : 'show-err');
}

/* Event wiring */
document.getElementById('themeSwitch').addEventListener('click', toggleTheme);
document.querySelectorAll('.nav-item[data-page]').forEach((btn) => btn.addEventListener('click', () => navigate(btn.dataset.page)));

document.getElementById('historyFilter').addEventListener('change', renderHistory);

document.getElementById('verifyReceiverBtn').addEventListener('click', async () => {
  const form = document.getElementById('bankTransferForm');
  const accountNumber = form.destinationAccount.value;
  const ifscCode = form.destinationIfsc.value;
  const msg = document.getElementById('verifyReceiverMsg');

  if (!accountNumber || !ifscCode) {
    msg.textContent = 'Enter receiver account and IFSC first.';
    msg.className = 'verify-result show-err';
    return;
  }

  try {
    const r = await api(`/api/v1/payments/verify-receiver?accountNumber=${encodeURIComponent(accountNumber)}&ifscCode=${encodeURIComponent(ifscCode)}`);
    msg.textContent = r.message;
    msg.className = 'verify-result ' + (r.internalAccount ? 'show-ok' : 'show-info');
    if (r.internalAccount && !form.receiverName.value) form.receiverName.value = r.receiverName;
  } catch (e) {
    msg.textContent = e.message;
    msg.className = 'verify-result show-err';
  }
});

document.getElementById('bankAccountForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const f = e.target;
  try {
    await api('/api/v1/bank-accounts', {
      method: 'POST',
      body: JSON.stringify({
        accountHolderName: f.accountHolderName.value,
        bankName: f.bankName.value,
        accountNumber: f.accountNumber.value,
        ifscCode: f.ifscCode.value,
        accountType: f.accountType.value,
        bankPin: f.bankPin.value,
        openingBalance: Number(f.openingBalance.value)
      })
    });
    f.reset();
    showResult('bankAccountResult', 'Bank account linked successfully.', true);
    await loadAll();
  } catch (err) {
    showResult('bankAccountResult', err.message, false);
  }
});

document.getElementById('upiRecipientType').addEventListener('change', function () {
  const isMobile = this.value === 'mobile';
  document.getElementById('upiIdGroup').style.display = isMobile ? 'none' : '';
  document.getElementById('mobileGroup').style.display = isMobile ? '' : 'none';
  document.getElementById('upiIdInput').required = !isMobile;
  document.getElementById('mobileInput').required = isMobile;
});

document.getElementById('upiForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const f = e.target;
  const recipientType = document.getElementById('upiRecipientType').value;

  let destinationUpiId = '';
  if (recipientType === 'mobile') {
    const mobile = document.getElementById('mobileInput').value.trim();
    if (!/^\d{10}$/.test(mobile)) {
      showResult('upiResult', 'Enter a valid 10-digit mobile number.', false);
      return;
    }
    destinationUpiId = mobile + '@mobile';
  } else {
    destinationUpiId = document.getElementById('upiIdInput').value.trim();
    if (!destinationUpiId) {
      showResult('upiResult', 'Enter a UPI ID.', false);
      return;
    }
  }

  try {
    const p = await api('/api/v1/payments/pay-to-upi', {
      method: 'POST',
      body: JSON.stringify({
        sourceAccountId: Number(f.sourceAccountId.value),
        amount: Number(f.amount.value),
        currency: f.currency.value,
        destinationUpiId,
        idempotencyKey: f.idempotencyKey.value,
        appPin: f.appPin.value,
        bankPin: f.bankPin.value
      })
    });
    f.reset();
    document.getElementById('upiRecipientType').value = 'upi';
    document.getElementById('upiIdGroup').style.display = '';
    document.getElementById('mobileGroup').style.display = 'none';
    showResult('upiResult', `Payment ${p.status}. ID: ${p.id.slice(0, 8)}...`, true);
    await loadAll();
  } catch (err) {
    showResult('upiResult', err.message, false);
  }
});

document.getElementById('bankTransferForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const f = e.target;
  try {
    const p = await api('/api/v1/payments/pay-to-bank', {
      method: 'POST',
      body: JSON.stringify({
        sourceAccountId: Number(f.sourceAccountId.value),
        amount: Number(f.amount.value),
        currency: f.currency.value,
        receiverName: f.receiverName.value || null,
        destinationAccount: f.destinationAccount.value || null,
        destinationIfsc: f.destinationIfsc.value || null,
        reference: f.reference.value || null,
        idempotencyKey: f.idempotencyKey.value,
        appPin: f.appPin.value,
        bankPin: f.bankPin.value
      })
    });
    f.reset();
    showResult('bankTransferResult', `Transfer ${p.status}. ID: ${p.id.slice(0, 8)}...`, true);
    await loadAll();
  } catch (err) {
    showResult('bankTransferResult', err.message, false);
  }
});

async function loadAll() {
  state.user = await api('/api/v1/auth/me');
  if (!state.user) return;

  [state.accounts, state.payments, state.audits, state.summary] = await Promise.all([
    api('/api/v1/bank-accounts'),
    api('/api/v1/payments'),
    api('/api/v1/payments/audits'),
    api('/api/v1/dashboard/summary')
  ]);

  renderSidebar();
  renderKPIs();
  renderCharts();
  renderHistory();
  renderAudits();
  renderAccounts();
  renderDashboardRecent();
  renderProfile();
}

const auditStatusFilter = document.getElementById('auditStatusFilter');
if (auditStatusFilter) auditStatusFilter.addEventListener('change', renderAudits);

window.deleteBankAccount = deleteBankAccount;
window.openAuditPayment = openAuditPayment;
window.showPaymentDetail = showPaymentDetail;
window.loadAll = loadAll;
window.navigate = navigate;

applyTheme(getTheme());
loadAll().catch((err) => console.error('Failed to load dashboard', err));

/* TruePay dashboard frontend */
const state = { user: null, accounts: [], payments: [], audits: [], summary: null, charts: {}, searchQuery: '' };

/* Theme */
function getTheme() {
  return localStorage.getItem('theme') || 'dark';
}

function applyTheme(theme) {
  const dark = theme === 'dark';
  document.body.classList.toggle('dark', dark);
  document.getElementById('themeSwitch').classList.toggle('on', dark);
}

function toggleTheme() {
  const next = getTheme() === 'dark' ? 'light' : 'dark';
  localStorage.setItem('theme', next);
  applyTheme(next);
}

/* Navigation */
function navigate(page) {
  document.querySelectorAll('.page').forEach((p) => p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach((n) => n.classList.remove('active'));

  const pageEl = document.getElementById('page-' + page);
  if (pageEl) pageEl.classList.add('active');

  const navEl = document.querySelector(`.nav-item[data-page="${page}"]`);
  if (navEl) navEl.classList.add('active');

  const titles = {
    dashboard: ['Dashboard', "Welcome back! Here's your overview."],
    history: ['Payment History', 'All your transactions in one place.'],
    audits: ['Audit History', 'Every transaction event, actor, and status change.'],
    'pay-upi': ['Pay to UPI', 'Send money instantly via UPI.'],
    'pay-bank': ['Bank Transfer', 'Transfer funds to any bank account.'],
    accounts: ['Bank Accounts', 'Manage your linked accounts.'],
    profile: ['Profile', 'Your personal information.']
  };

  const [title, sub] = titles[page] || ['TruePay', ''];
  document.getElementById('topbarTitle').textContent = title;
  document.getElementById('topbarSub').textContent = sub;
}

/* API */
async function api(path, options = {}) {
  const res = await fetch(path, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(options.headers || {})
    }
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || 'Request failed');
  }

  if (res.status === 204) return null;
  return res.json().catch(() => null);
}

/* Formatting */
function inr(v) {
  return 'INR ' + Number(v || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function maskNum(n) {
  return n ? '**** ' + n.slice(-4) : '-';
}

function fmtDate(d) {
  return d ? new Date(d).toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '-';
}

function statusIcon(s) {
  return { COMPLETED: 'OK', FAILED: 'X', CREATED: 'NEW', VALIDATED: 'CHK', SENT: 'SENT' }[s] || '...';
}

function toSearchText(value) {
  return String(value || '').toLowerCase().trim();
}

function paymentMatchesQuery(payment, query) {
  if (!query) return true;
  const haystack = [
    payment.id,
    payment.method,
    payment.status,
    payment.receiverName,
    payment.destinationUpiId,
    payment.currency,
    payment.amount,
    fmtDate(payment.createdAt)
  ].map(toSearchText).join(' ');
  return haystack.includes(query);
}

function auditMatchesQuery(audit, query) {
  if (!query) return true;
  const haystack = [
    audit.paymentId,
    audit.method,
    audit.status,
    audit.receiver,
    audit.currency,
    audit.amount,
    audit.triggeredBy,
    audit.notes,
    audit.referenceRemark,
    fmtDate(audit.changedAt)
  ].map(toSearchText).join(' ');
  return haystack.includes(query);
}

function accountMatchesQuery(account, query) {
  if (!query) return true;
  const haystack = [
    account.bankName,
    account.accountHolderName,
    account.accountNumber,
    account.ifscCode,
    account.accountType,
    account.balance
  ].map(toSearchText).join(' ');
  return haystack.includes(query);
}

function getSearchTargetPage(query) {
  if (!query) return null;

  const pageKeywords = {
    dashboard: ['dashboard', 'overview', 'summary', 'kpi', 'risk'],
    history: ['history', 'payment history', 'payments', 'transactions'],
    audits: ['audit', 'audit history', 'events', 'actor', 'timeline'],
    'pay-upi': ['upi', 'pay upi', 'send upi', 'mobile'],
    'pay-bank': ['bank transfer', 'transfer', 'ifsc', 'receiver'],
    accounts: ['account', 'bank accounts', 'ifsc', 'balance', 'linked'],
    profile: ['profile', 'user', 'email', 'mobile']
  };

  for (const [page, words] of Object.entries(pageKeywords)) {
    if (words.some((word) => word.includes(query) || query.includes(word))) {
      return page;
    }
  }

  if (state.payments.some((p) => paymentMatchesQuery(p, query))) return 'history';
  if (state.audits.some((a) => auditMatchesQuery(a, query))) return 'audits';
  if (state.accounts.some((a) => accountMatchesQuery(a, query))) return 'accounts';

  if (state.user) {
    const userText = [state.user.fullName, state.user.email, state.user.mobile].map(toSearchText).join(' ');
    if (userText.includes(query)) return 'profile';
  }

  return null;
}

function runSearch(query, options = {}) {
  state.searchQuery = toSearchText(query);

  const searchWrap = document.querySelector('.topbar-search-wrap');
  if (searchWrap) {
    searchWrap.classList.toggle('search-active', Boolean(state.searchQuery));
  }

  if (options.navigateFirstMatch) {
    const targetPage = getSearchTargetPage(state.searchQuery);
    if (targetPage) navigate(targetPage);
  }

  renderHistory();
  renderAudits();
  renderAccounts();
  renderDashboardRecent();
}

/* Render */
function renderSidebar() {
  if (!state.user) return;
  const sidebarName = document.getElementById('sidebarName');
  const sidebarEmail = document.getElementById('sidebarEmail');
  const sidebarAvatar = document.getElementById('sidebarAvatar');

  if (sidebarName) sidebarName.textContent = state.user.fullName;
  if (sidebarEmail) sidebarEmail.textContent = state.user.email;
  if (sidebarAvatar) sidebarAvatar.textContent = state.user.fullName.charAt(0).toUpperCase();
}

function renderKPIs() {
  if (!state.summary) return;
  const s = state.summary;
  document.getElementById('kpiBalance').textContent = inr(s.combinedBalance);
  document.getElementById('kpiAccounts').textContent = s.linkedBankAccounts + ' accounts linked';
  document.getElementById('kpiCompleted').textContent = s.completedPayments;
  document.getElementById('kpiFailed').textContent = s.failedPayments;
  document.getElementById('kpiFraud').textContent = s.fraudAlerts;
  document.getElementById('chartTotalLabel').textContent = s.totalPayments + ' total payments';
}

function renderCharts() {
  if (!state.summary) return;

  ['volumeChart', 'statusChart', 'methodChart', 'riskChart'].forEach((id) => {
    if (state.charts[id]) state.charts[id].destroy();
  });

  const s = state.summary;
  const completed = s.completedPayments;
  const failed = s.failedPayments;
  const inProgress = Math.max(0, s.totalPayments - completed - failed);

  const lastSeven = [0, 0, 0, 0, 0, 0, 0];
  const now = new Date();
  state.payments.forEach((p) => {
    const days = Math.floor((now - new Date(p.createdAt)) / 86400000);
    if (days >= 0 && days < 7) lastSeven[6 - days] += 1;
  });
  const labels = [...Array(7)].map((_, i) => {
    const d = new Date(now);
    d.setDate(d.getDate() - (6 - i));
    return (d.getMonth() + 1) + '/' + d.getDate();
  });

  state.charts.volumeChart = new Chart(document.getElementById('volumeChart'), {
    type: 'line',
    data: { labels, datasets: [{ label: 'Payments', data: lastSeven, borderColor: '#7c5cfc', tension: 0.35 }] },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1
          }
        }
      }
    }
  });

  state.charts.statusChart = new Chart(document.getElementById('statusChart'), {
    type: 'doughnut',
    data: { labels: ['Completed', 'Failed', 'In Progress'], datasets: [{ data: [completed, failed, inProgress], backgroundColor: ['#22c55e', '#ef4444', '#7c5cfc'] }] },
    options: { responsive: true, cutout: '65%', plugins: { legend: { display: false } } }
  });

  const upiCount = state.payments.filter((p) => p.method === 'UPI').length;
  const bankCount = state.payments.filter((p) => p.method === 'BANK').length;
  state.charts.methodChart = new Chart(document.getElementById('methodChart'), {
    type: 'bar',
    data: { labels: ['UPI', 'Bank Transfer'], datasets: [{ data: [upiCount, bankCount], backgroundColor: ['rgba(124,92,252,.8)', 'rgba(79,140,255,.8)'] }] },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1
          }
        }
      }
    }
  });

  state.charts.riskChart = new Chart(document.getElementById('riskChart'), {
    type: 'bar',
    data: { labels: ['Completed', 'Failed', 'Fraud Alerts'], datasets: [{ data: [completed, failed, s.fraudAlerts], backgroundColor: ['rgba(34,197,94,.7)', 'rgba(239,68,68,.7)', 'rgba(251,146,60,.7)'] }] },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1
          }
        }
      }
    }
  });

  const total = completed + failed + inProgress || 1;
  document.getElementById('distList').innerHTML = [
    { label: 'Completed', val: completed, color: '#22c55e' },
    { label: 'Failed', val: failed, color: '#ef4444' },
    { label: 'In Progress', val: inProgress, color: '#7c5cfc' }
  ].map((d) => `<div class="dist-item"><div class="dist-dot" style="background:${d.color}"></div><span class="dist-label">${d.label}</span><span class="dist-val">${d.val}</span><span class="dist-pct">${Math.round((d.val / total) * 100)}%</span></div>`).join('');
}

function renderHistory() {
  const filter = document.getElementById('historyFilter').value;
  const query = state.searchQuery;
  const byStatus = filter ? state.payments.filter((p) => p.status === filter) : state.payments;
  const data = byStatus.filter((p) => paymentMatchesQuery(p, query));
  const tbody = document.getElementById('historyTableBody');

  if (!data.length) {
    const emptyMessage = query ? 'No payments match your search.' : 'No payments found.';
    tbody.innerHTML = `<tr><td colspan="7" class="empty">${emptyMessage}</td></tr>`;
    return;
  }

  tbody.innerHTML = data.slice(0, 50).map((p) => `
    <tr>
      <td style="font-family:monospace;font-size:11px;color:var(--text-sub);">${p.id.slice(0, 8)}...</td>
      <td><span class="tag tag-${p.method === 'UPI' ? 'upi' : 'bank'}">${p.method}</span></td>
      <td>${p.receiverName || p.destinationUpiId || '-'}</td>
      <td style="font-weight:700;">${p.amount} <span style="color:var(--text-sub);font-size:11px;">${p.currency}</span></td>
      <td><span class="status-badge ${p.status}">${statusIcon(p.status)} ${p.status}</span></td>
      <td style="color:var(--text-sub);">${fmtDate(p.createdAt)}</td>
      <td><button class="btn btn-secondary" style="padding:5px 10px;font-size:11px;" onclick="showPaymentDetail('${p.id}')">Detail</button></td>
    </tr>`).join('');
}

function renderAccounts() {
  document.getElementById('accCombined').textContent = state.summary ? inr(state.summary.combinedBalance) : 'INR 0.00';

  const query = state.searchQuery;
  const visibleAccounts = state.accounts.filter((a) => accountMatchesQuery(a, query));

  const html = visibleAccounts.map((a) => `
    <div class="account-chip">
      <div class="account-chip-icon">B</div>
      <div class="account-chip-info">
        <div class="account-chip-bank">${a.bankName}</div>
        <div class="account-chip-num">${maskNum(a.accountNumber)} | ${a.ifscCode}</div>
        <div style="font-size:11px;color:var(--text-sub);margin-top:2px;">${a.accountHolderName || ''} ${a.accountType ? '· <span class="tag" style="font-size:10px;padding:2px 6px;">' + a.accountType + '</span>' : ''}</div>
      </div>
      <div class="account-chip-bal">${inr(a.balance)}</div>
      <button class="btn btn-danger" onclick="deleteBankAccount(${a.id})">Delete</button>
    </div>`).join('');

  const emptyMessage = query ? 'No bank accounts match your search.' : 'No bank accounts linked yet.';
  document.getElementById('accountsList').innerHTML = html || `<div class="empty">${emptyMessage}</div>`;
  document.getElementById('upiAccountPreview').innerHTML = html || '<div class="empty">No accounts.</div>';

  const options = state.accounts.map((a) => `<option value="${a.id}">${a.bankName} | ${maskNum(a.accountNumber)} (${inr(a.balance)})</option>`).join('');
  ['upiSource', 'bankSource'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = options;
  });

  const sideList = visibleAccounts.slice(0, 5).map((a) => `
    <div class="dashboard-account-item">
      <div>
        <div class="dashboard-account-bank">${a.bankName}</div>
        <div class="dashboard-account-num">${maskNum(a.accountNumber)}${a.accountType ? ' · ' + a.accountType : ''}</div>
      </div>
      <div class="dashboard-account-bal">${inr(a.balance)}</div>
    </div>`).join('');
  const dashboardAccounts = document.getElementById('dashboardBankAccountsList');
  if (dashboardAccounts) {
    const sideEmptyMessage = query ? 'No linked accounts match your search.' : 'No linked accounts yet.';
    dashboardAccounts.innerHTML = sideList || `<div class="empty">${sideEmptyMessage}</div>`;
  }
}

function renderDashboardRecent() {
  const tbody = document.getElementById('dashboardRecentBody');
  if (!tbody) return;

  const query = state.searchQuery;
  const visiblePayments = state.payments.filter((p) => paymentMatchesQuery(p, query));

  if (!visiblePayments.length) {
    const emptyMessage = query ? 'No recent transactions match your search.' : 'No recent transactions.';
    tbody.innerHTML = `<tr><td colspan="4" class="empty">${emptyMessage}</td></tr>`;
    return;
  }

  tbody.innerHTML = visiblePayments.slice(0, 6).map((p) => `
    <tr>
      <td style="font-family:monospace;font-size:11px;color:var(--text-sub);">${p.id.slice(0, 8)}...</td>
      <td>${p.receiverName || p.destinationUpiId || '-'}</td>
      <td style="font-weight:700;">${p.amount} ${p.currency}</td>
      <td><span class="status-badge ${p.status}">${p.status}</span></td>
    </tr>`).join('');
}

function renderProfile() {
  if (!state.user) return;
  document.getElementById('profileContent').innerHTML = `
    <div class="account-chip" style="margin-bottom:12px;">
      <div class="sidebar-avatar">${state.user.fullName.charAt(0).toUpperCase()}</div>
      <div class="account-chip-info">
        <div class="account-chip-bank">${state.user.fullName}</div>
        <div class="account-chip-num">${state.user.email}</div>
      </div>
    </div>
    <div style="font-size:14px;display:flex;flex-direction:column;gap:10px;">
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">Full Name</span><strong>${state.user.fullName}</strong></div>
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">Email</span><strong>${state.user.email}</strong></div>
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">Mobile</span><strong>${state.user.mobile}</strong></div>
      <div class="flex-center"><span style="color:var(--text-sub);min-width:100px;">User ID</span><strong>#${state.user.id}</strong></div>
    </div>`;
}

function renderAudits() {
  const tbody = document.getElementById('auditTableBody');
  if (!tbody) return;

  const filter = document.getElementById('auditStatusFilter')?.value || '';
  const query = state.searchQuery;
  const byStatus = filter ? state.audits.filter((audit) => audit.status === filter) : state.audits;
  const data = byStatus.filter((audit) => auditMatchesQuery(audit, query));

  const eventCount = document.getElementById('auditEventCount');
  const transactionCount = document.getElementById('auditTransactionCount');
  const latestAt = document.getElementById('auditLatestAt');

  if (eventCount) eventCount.textContent = data.length;
  if (transactionCount) transactionCount.textContent = new Set(data.map((audit) => audit.paymentId)).size;
  if (latestAt) latestAt.textContent = data.length ? fmtDate(data[0].changedAt) : '-';

  if (!data.length) {
    const emptyMessage = query ? 'No audit events match your search.' : 'No audit events found.';
    tbody.innerHTML = `<tr><td colspan="9" class="empty">${emptyMessage}</td></tr>`;
    return;
  }

  tbody.innerHTML = data.slice(0, 100).map((audit) => `
    <tr>
      <td style="color:var(--text-sub);">${fmtDate(audit.changedAt)}</td>
      <td style="font-family:monospace;font-size:11px;color:var(--text-sub);">${audit.paymentId.slice(0, 8)}...</td>
      <td><span class="tag tag-${audit.method === 'UPI' ? 'upi' : 'bank'}">${audit.method}</span></td>
      <td>${audit.receiver || '-'}</td>
      <td style="font-weight:700;">${audit.amount} <span style="color:var(--text-sub);font-size:11px;">${audit.currency}</span></td>
      <td><span class="status-badge ${audit.status}">${statusIcon(audit.status)} ${audit.status}</span></td>
      <td>${audit.triggeredBy}</td>
      <td>
        <div>${audit.notes || '-'}</div>
        ${audit.referenceRemark ? `<div class="audit-reference">Ref: ${audit.referenceRemark}</div>` : ''}
      </td>
      <td><button class="btn btn-secondary" style="padding:5px 10px;font-size:11px;" onclick="openAuditPayment('${audit.paymentId}')">Transaction</button></td>
    </tr>`).join('');
}

async function showPaymentDetail(paymentId) {
  const payment = state.payments.find((p) => p.id === paymentId);
  if (!payment) return;

  const content = document.getElementById('paymentDetailContent');
  content.innerHTML = `
    <div class="page-grid-2" style="margin-bottom:12px;">
      <div><div class="kpi-label">Payment ID</div><div style="font-family:monospace;font-size:12px;">${payment.id}</div></div>
      <div><div class="kpi-label">Status</div><span class="status-badge ${payment.status}">${statusIcon(payment.status)} ${payment.status}</span></div>
      <div><div class="kpi-label">Amount</div><div style="font-weight:700;">${payment.amount} ${payment.currency}</div></div>
      <div><div class="kpi-label">Method</div><span class="tag tag-${payment.method === 'UPI' ? 'upi' : 'bank'}">${payment.method}</span></div>
      <div><div class="kpi-label">Receiver</div><div>${payment.receiverName || payment.destinationUpiId || '-'}</div></div>
      <div><div class="kpi-label">Reference</div><div>${payment.referenceRemark || '-'}</div></div>
      <div><div class="kpi-label">Created</div><div style="color:var(--text-sub);">${fmtDate(payment.createdAt)}</div></div>
      ${payment.errorMessage ? `<div style="grid-column:1/-1;"><div class="kpi-label">Error</div><div style="color:var(--red);">${payment.errorMessage}</div></div>` : ''}
    </div>`;

  document.getElementById('paymentDetailPanel').style.display = 'block';

  try {
    const history = await api(`/api/v1/payments/${paymentId}/history`);
    document.getElementById('paymentTimeline').innerHTML = (history || []).map((h) => `
      <div class="timeline-item">
        <div class="timeline-dot ${h.status}">${statusIcon(h.status)}</div>
        <div class="timeline-content">
          <div class="timeline-label">${h.status}</div>
          <div class="timeline-time">${fmtDate(h.changedAt)} by ${h.triggeredBy}</div>
          <div class="timeline-note">${h.notes || ''}</div>
        </div>
      </div>`).join('');
  } catch (_) {
    document.getElementById('paymentTimeline').innerHTML = '';
  }
}

function openAuditPayment(paymentId) {
  navigate('history');
  showPaymentDetail(paymentId);
}

/* Actions */
async function deleteBankAccount(id) {
  if (!confirm('Delete this bank account? Only allowed with zero balance.')) return;
  try {
    await api(`/api/v1/bank-accounts/${id}`, { method: 'DELETE' });
    await loadAll();
  } catch (e) {
    alert(e.message);
  }
}

/* Form helpers */
function showResult(id, message, ok) {
  const el = document.getElementById(id);
  el.textContent = message;
  el.className = 'verify-result ' + (ok ? 'show-ok' : 'show-err');
}

/* Event wiring */
document.getElementById('themeSwitch').addEventListener('click', toggleTheme);
document.querySelectorAll('.nav-item[data-page]').forEach((btn) => btn.addEventListener('click', () => navigate(btn.dataset.page)));

document.getElementById('historyFilter').addEventListener('change', renderHistory);

const topbarSearchInput = document.getElementById('globalSearch');
if (topbarSearchInput) {
  topbarSearchInput.addEventListener('input', (e) => {
    runSearch(e.target.value);
  });

  topbarSearchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      runSearch(e.target.value, { navigateFirstMatch: true });
    }

    if (e.key === 'Escape') {
      e.preventDefault();
      e.target.value = '';
      runSearch('');
    }
  });
}

document.getElementById('verifyReceiverBtn').addEventListener('click', async () => {
  const form = document.getElementById('bankTransferForm');
  const accountNumber = form.destinationAccount.value;
  const ifscCode = form.destinationIfsc.value;
  const msg = document.getElementById('verifyReceiverMsg');

  if (!accountNumber || !ifscCode) {
    msg.textContent = 'Enter receiver account and IFSC first.';
    msg.className = 'verify-result show-err';
    return;
  }

  try {
    const r = await api(`/api/v1/payments/verify-receiver?accountNumber=${encodeURIComponent(accountNumber)}&ifscCode=${encodeURIComponent(ifscCode)}`);
    msg.textContent = r.message;
    msg.className = 'verify-result ' + (r.internalAccount ? 'show-ok' : 'show-info');
    if (r.internalAccount && !form.receiverName.value) form.receiverName.value = r.receiverName;
  } catch (e) {
    msg.textContent = e.message;
    msg.className = 'verify-result show-err';
  }
});

document.getElementById('bankAccountForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const f = e.target;
  try {
    await api('/api/v1/bank-accounts', {
      method: 'POST',
      body: JSON.stringify({
        accountHolderName: f.accountHolderName.value,
        bankName: f.bankName.value,
        accountNumber: f.accountNumber.value,
        ifscCode: f.ifscCode.value,
        accountType: f.accountType.value,
        bankPin: f.bankPin.value,
        openingBalance: Number(f.openingBalance.value)
      })
    });
    f.reset();
    showResult('bankAccountResult', 'Bank account linked successfully.', true);
    await loadAll();
  } catch (err) {
    showResult('bankAccountResult', err.message, false);
  }
});

document.getElementById('upiRecipientType').addEventListener('change', function () {
  const isMobile = this.value === 'mobile';
  document.getElementById('upiIdGroup').style.display = isMobile ? 'none' : '';
  document.getElementById('mobileGroup').style.display = isMobile ? '' : 'none';
  document.getElementById('upiIdInput').required = !isMobile;
  document.getElementById('mobileInput').required = isMobile;
});

document.getElementById('upiForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const f = e.target;
  const recipientType = document.getElementById('upiRecipientType').value;

  let destinationUpiId = '';
  if (recipientType === 'mobile') {
    const mobile = document.getElementById('mobileInput').value.trim();
    if (!/^\d{10}$/.test(mobile)) {
      showResult('upiResult', 'Enter a valid 10-digit mobile number.', false);
      return;
    }
    destinationUpiId = mobile + '@mobile';
  } else {
    destinationUpiId = document.getElementById('upiIdInput').value.trim();
    if (!destinationUpiId) {
      showResult('upiResult', 'Enter a UPI ID.', false);
      return;
    }
  }

  try {
    const p = await api('/api/v1/payments/pay-to-upi', {
      method: 'POST',
      body: JSON.stringify({
        sourceAccountId: Number(f.sourceAccountId.value),
        amount: Number(f.amount.value),
        currency: f.currency.value,
        destinationUpiId,
        idempotencyKey: f.idempotencyKey.value,
        appPin: f.appPin.value,
        bankPin: f.bankPin.value
      })
    });
    f.reset();
    document.getElementById('upiRecipientType').value = 'upi';
    document.getElementById('upiIdGroup').style.display = '';
    document.getElementById('mobileGroup').style.display = 'none';
    showResult('upiResult', `Payment ${p.status}. ID: ${p.id.slice(0, 8)}...`, true);
    await loadAll();
  } catch (err) {
    showResult('upiResult', err.message, false);
  }
});

document.getElementById('bankTransferForm').addEventListener('submit', async (e) => {
  e.preventDefault();
  const f = e.target;
  try {
    const p = await api('/api/v1/payments/pay-to-bank', {
      method: 'POST',
      body: JSON.stringify({
        sourceAccountId: Number(f.sourceAccountId.value),
        amount: Number(f.amount.value),
        currency: f.currency.value,
        receiverName: f.receiverName.value || null,
        destinationAccount: f.destinationAccount.value || null,
        destinationIfsc: f.destinationIfsc.value || null,
        reference: f.reference.value || null,
        idempotencyKey: f.idempotencyKey.value,
        appPin: f.appPin.value,
        bankPin: f.bankPin.value
      })
    });
    f.reset();
    showResult('bankTransferResult', `Transfer ${p.status}. ID: ${p.id.slice(0, 8)}...`, true);
    await loadAll();
  } catch (err) {
    showResult('bankTransferResult', err.message, false);
  }
});

async function loadAll() {
  state.user = await api('/api/v1/auth/me');
  if (!state.user) return;

  [state.accounts, state.payments, state.audits, state.summary] = await Promise.all([
    api('/api/v1/bank-accounts'),
    api('/api/v1/payments'),
    api('/api/v1/payments/audits'),
    api('/api/v1/dashboard/summary')
  ]);

  renderSidebar();
  renderKPIs();
  renderCharts();
  renderHistory();
  renderAudits();
  renderAccounts();
  renderDashboardRecent();
  renderProfile();
  runSearch(state.searchQuery);
}

const auditStatusFilter = document.getElementById('auditStatusFilter');
if (auditStatusFilter) auditStatusFilter.addEventListener('change', renderAudits);

window.deleteBankAccount = deleteBankAccount;
window.openAuditPayment = openAuditPayment;
window.showPaymentDetail = showPaymentDetail;
window.loadAll = loadAll;
window.navigate = navigate;

applyTheme(getTheme());
loadAll().catch((err) => console.error('Failed to load dashboard', err));

/* ─── Variables ───────────────────────────────────────────────────── */
:root {
  --bg: #f0f2f9;
  --sidebar-bg: #ffffff;
  --card: #ffffff;
  --card2: #f7f8fd;
  --text: #1a1a2e;
  --text-sub: #6b6f8a;
  --border: #e2e5f0;
  --accent: #5f3dc4;
  --accent-light: #ede9ff;
  --accent2: #3b82f6;
  --green: #22c55e;
  --green-bg: #dcfce7;
  --red: #ef4444;
  --red-bg: #fee2e2;
  --shadow: 0 2px 16px rgba(60,60,100,.08);
  --shadow-lg: 0 8px 32px rgba(60,60,100,.14);
  --radius: 14px;
  --sidebar-w: 230px;
}

body.dark {
  --bg: #080810;
  --sidebar-bg: #0e0e1c;
  --card: #12121e;
  --card2: #1a1a2c;
  --text: #eeeeff;
  --text-sub: #8888aa;
  --border: #1e1e34;
  --accent: #7c5cfc;
  --accent-light: #2a1f50;
  --accent2: #4f8cff;
  --green: #22c55e;
  --green-bg: #0e2e1c;
  --red: #f87171;
  --red-bg: #2e0e0e;
  --shadow: 0 2px 16px rgba(0,0,0,.35);
  --shadow-lg: 0 8px 40px rgba(0,0,0,.5);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg);
  color: var(--text);
  transition: background .25s, color .25s;
}

a { text-decoration: none; color: inherit; }

.app-shell { display: flex; min-height: 100vh; }

/* Sidebar */
.sidebar {
  width: var(--sidebar-w); flex-shrink: 0;
  background: var(--sidebar-bg);
  border-right: 1px solid var(--border);
  display: flex; flex-direction: column;
  padding: 24px 0 16px;
  position: fixed; top: 0; left: 0; height: 100vh; z-index: 100;
  transition: background .25s, border-color .25s;
}

.sidebar-logo {
  display: flex; align-items: center; gap: 10px;
  padding: 0 20px 24px; border-bottom: 1px solid var(--border);
}

.logo-image { width: 34px; height: 34px; object-fit: contain; border-radius: 8px; flex-shrink: 0; }

.logo-text { font-size: 18px; font-weight: 700; }
.logo-tag { font-size: 10px; color: var(--text-sub); }

.sidebar-nav { flex: 1; padding: 16px 12px; display: flex; flex-direction: column; gap: 4px; }
.nav-section-label { font-size: 10px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--text-sub); padding: 12px 8px 4px; }

.nav-item {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 10px;
  font-size: 14px; font-weight: 500; cursor: pointer;
  color: var(--text-sub); transition: all .18s;
  border: none; background: none; width: 100%; text-align: left;
}

.nav-item:hover { background: var(--accent-light); color: var(--accent); }
.nav-item.active { background: var(--accent-light); color: var(--accent); font-weight: 600; }
.nav-item .icon { font-size: 16px; width: 20px; text-align: center; }

.sidebar-bottom { padding: 12px 20px; border-top: 1px solid var(--border); }

.sidebar-user { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }

.sidebar-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-weight: 700; font-size: 14px; flex-shrink: 0;
}

.sidebar-user-info { flex: 1; overflow: hidden; }
.sidebar-user-name { font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sidebar-user-email { font-size: 11px; color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.theme-toggle-row { display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--text-sub); padding: 4px 0; }

.toggle-switch {
  width: 42px; height: 24px; background: var(--border);
  border-radius: 12px; position: relative; cursor: pointer;
  transition: background .2s; border: none;
}

.toggle-switch.on { background: var(--accent); }
.toggle-knob { width: 18px; height: 18px; background: #fff; border-radius: 50%; position: absolute; top: 3px; left: 3px; transition: left .2s; }
.toggle-switch.on .toggle-knob { left: 21px; }

/* Main */
.main { margin-left: var(--sidebar-w); flex: 1; display: flex; flex-direction: column; min-height: 100vh; }

/* Topbar */
.topbar {
  height: 64px; display: flex; align-items: center; gap: 12px;
  padding: 0 28px; background: var(--card);
  border-bottom: 1px solid var(--border);
  position: sticky; top: 0; z-index: 90;
  transition: background .25s, border-color .25s;
}

.topbar-title { font-size: 20px; font-weight: 700; }
.topbar-sub { font-size: 13px; color: var(--text-sub); }
.spacer { flex: 1; }

.balance-chip {
  display: flex; align-items: center; gap: 10px;
  background: var(--card2); border: 1px solid var(--border);
  border-radius: 12px; padding: 8px 16px;
}

.balance-chip .label { color: var(--text-sub); font-weight: 400; font-size: 12px; }
.balance-chip .amount { font-size: 16px; font-weight: 700; }

.topbar-actions { display: flex; gap: 8px; }

.btn { border: none; border-radius: 10px; cursor: pointer; font-weight: 600; transition: all .18s; display: inline-flex; align-items: center; gap: 6px; font-size: 13px; }
.btn-primary { background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; padding: 9px 18px; }
.btn-primary:hover { opacity: .88; transform: translateY(-1px); }
.btn-secondary { background: var(--card2); border: 1px solid var(--border); color: var(--text); padding: 9px 14px; }
.btn-secondary:hover { background: var(--accent-light); color: var(--accent); border-color: var(--accent); }
.btn-icon { width: 38px; height: 38px; padding: 0; justify-content: center; }
.btn-danger { background: var(--red-bg); color: var(--red); border: 1px solid transparent; padding: 7px 12px; font-size: 12px; border-radius: 8px; }
.btn-danger:hover { border-color: var(--red); }
.btn-logout { background: none; border: 1px solid var(--border); color: var(--text-sub); padding: 8px 14px; border-radius: 8px; font-size: 13px; cursor: pointer; font-weight: 500; }
.btn-logout:hover { border-color: var(--red); color: var(--red); }

/* Pages */
.page { padding: 24px 28px; display: none; }
.page.active { display: block; }

.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.section-title { font-size: 16px; font-weight: 700; }

/* KPI Grid */
.kpi-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; margin-bottom: 20px; }

.kpi-card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  box-shadow: var(--shadow); transition: background .25s, border-color .25s;
}

.kpi-label { font-size: 13px; color: var(--text-sub); margin-bottom: 8px; }
.kpi-value { font-size: 26px; font-weight: 800; letter-spacing: -.5px; }
.kpi-badge { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 600; padding: 3px 8px; border-radius: 20px; margin-top: 8px; }
.kpi-badge.up { background: var(--green-bg); color: var(--green); }
.kpi-badge.down { background: var(--red-bg); color: var(--red); }
.kpi-badge.neutral { background: var(--accent-light); color: var(--accent); }

/* Charts */
.chart-grid { display: grid; grid-template-columns: 1.6fr 1fr; gap: 16px; margin-bottom: 20px; }

.chart-card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  box-shadow: var(--shadow); transition: background .25s, border-color .25s;
}

.chart-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 16px; }
.chart-title { font-size: 14px; font-weight: 700; }
.chart-meta { font-size: 12px; color: var(--text-sub); }
.chart-amount { font-size: 22px; font-weight: 800; margin-bottom: 2px; }
.chart-delta { font-size: 12px; color: var(--green); font-weight: 600; }

/* Dist bar */
.dist-bar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; margin: 12px 0 16px; gap: 2px; }
.dist-seg { border-radius: 4px; }
.dist-list { display: flex; flex-direction: column; gap: 8px; }
.dist-item { display: flex; align-items: center; gap: 8px; font-size: 13px; }
.dist-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.dist-label { flex: 1; color: var(--text-sub); }
.dist-val { font-weight: 600; }
.dist-pct { font-size: 12px; color: var(--text-sub); margin-left: 4px; }

/* Forms */
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.form-grid.cols-1 { grid-template-columns: 1fr; }

.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-label { font-size: 12px; font-weight: 600; color: var(--text-sub); }

.form-input, .form-select {
  padding: 11px 14px; border-radius: 10px;
  border: 1.5px solid var(--border);
  background: var(--card2); color: var(--text);
  font-size: 14px; width: 100%;
  transition: border .15s, background .25s; outline: none;
}

.form-input:focus, .form-select:focus { border-color: var(--accent); background: var(--card); }
.form-input::placeholder { color: var(--text-sub); }
.form-section-title { font-size: 12px; font-weight: 700; color: var(--text-sub); margin: 14px 0 4px; padding-bottom: 6px; border-bottom: 1px solid var(--border); grid-column: 1 / -1; text-transform: uppercase; letter-spacing: .05em; }

/* Panels */
.panel {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  box-shadow: var(--shadow); margin-bottom: 16px;
  transition: background .25s, border-color .25s;
}

.panel-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.panel-title { font-size: 15px; font-weight: 700; }

/* Account chip */
.account-chip {
  display: flex; align-items: center; gap: 12px;
  background: var(--card2); border: 1.5px solid var(--border);
  border-radius: 12px; padding: 14px 16px; margin-bottom: 10px;
  transition: border-color .15s;
}

.account-chip:hover { border-color: var(--accent); }
.account-chip-icon { width: 38px; height: 38px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 18px; background: var(--accent-light); }
.account-chip-info { flex: 1; }
.account-chip-bank { font-size: 14px; font-weight: 600; }
.account-chip-num { font-size: 12px; color: var(--text-sub); }
.account-chip-bal { font-weight: 700; font-size: 14px; }

/* Table */
.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.data-table th { text-align: left; padding: 10px 14px; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; color: var(--text-sub); border-bottom: 1px solid var(--border); }
.data-table td { padding: 12px 14px; border-bottom: 1px solid var(--border); }
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--card2); }

/* Status badge */
.status-badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 700; }
.status-badge::before { content: ''; width: 6px; height: 6px; border-radius: 50%; display: inline-block; }
.status-badge.COMPLETED { background: var(--green-bg); color: var(--green); }
.status-badge.COMPLETED::before { background: var(--green); }
.status-badge.FAILED { background: var(--red-bg); color: var(--red); }
.status-badge.FAILED::before { background: var(--red); }
.status-badge.CREATED, .status-badge.VALIDATED, .status-badge.SENT { background: var(--accent-light); color: var(--accent); }
.status-badge.CREATED::before, .status-badge.VALIDATED::before, .status-badge.SENT::before { background: var(--accent); }

/* Timeline */
.timeline { display: flex; flex-direction: column; }
.timeline-item { display: flex; gap: 14px; padding-bottom: 20px; position: relative; }
.timeline-item:last-child { padding-bottom: 0; }
.timeline-item:not(:last-child)::after { content: ''; position: absolute; left: 15px; top: 32px; width: 2px; bottom: 0; background: var(--border); }
.timeline-dot { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; flex-shrink: 0; z-index: 1; }
.timeline-dot.COMPLETED { background: var(--green-bg); color: var(--green); }
.timeline-dot.FAILED { background: var(--red-bg); color: var(--red); }
.timeline-dot.CREATED, .timeline-dot.VALIDATED, .timeline-dot.SENT { background: var(--accent-light); color: var(--accent); }
.timeline-content { flex: 1; padding-top: 5px; }
.timeline-label { font-size: 13px; font-weight: 600; }
.timeline-time { font-size: 11px; color: var(--text-sub); }
.timeline-note { font-size: 12px; color: var(--text-sub); margin-top: 2px; }

/* Beneficiary */
.bene-card { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-radius: 12px; background: var(--card2); border: 1px solid var(--border); margin-bottom: 8px; }
.bene-avatar { width: 36px; height: 36px; border-radius: 50%; background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 14px; flex-shrink: 0; }
.bene-info { flex: 1; }
.bene-name { font-size: 14px; font-weight: 600; }
.bene-num { font-size: 12px; color: var(--text-sub); }

/* Verify */
.verify-result { padding: 10px 14px; border-radius: 10px; font-size: 13px; margin-top: 8px; font-weight: 500; display: none; }
.verify-result.show-ok { background: var(--green-bg); color: var(--green); display: block; }
.verify-result.show-info { background: var(--accent-light); color: var(--accent); display: block; }
.verify-result.show-err { background: var(--red-bg); color: var(--red); display: block; }

/* Auth */
.auth-page { min-height: 100vh; display: flex; align-items: center; justify-content: center; background: var(--bg); padding: 24px; }

.auth-split { display: grid; grid-template-columns: 1.2fr 1fr; max-width: 940px; width: 100%; border-radius: 20px; overflow: hidden; box-shadow: var(--shadow-lg); min-height: 580px; }

.auth-left { background: linear-gradient(160deg, #3b1fc7 0%, #0f0630 50%, #1d4ed8 100%); padding: 48px 40px; display: flex; flex-direction: column; justify-content: space-between; color: #fff; }
.auth-brand { font-size: 24px; font-weight: 800; margin-bottom: 4px; }
.auth-tagline { font-size: 13px; opacity: .7; margin-bottom: 40px; }
.auth-feature-list { display: flex; flex-direction: column; gap: 16px; }
.auth-feature { display: flex; gap: 12px; align-items: flex-start; }
.auth-feature-icon { width: 36px; height: 36px; background: rgba(255,255,255,.15); border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
.auth-feature-text h4 { font-size: 14px; font-weight: 600; margin-bottom: 2px; }
.auth-feature-text p { font-size: 12px; opacity: .7; }

.auth-right { background: var(--card); padding: 48px 40px; display: flex; flex-direction: column; justify-content: center; }
.auth-title { font-size: 22px; font-weight: 800; margin-bottom: 6px; }
.auth-subtitle { font-size: 14px; color: var(--text-sub); margin-bottom: 28px; }
.auth-form { display: flex; flex-direction: column; gap: 14px; }
.auth-btn { padding: 13px; border-radius: 12px; border: none; background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; font-size: 15px; font-weight: 700; cursor: pointer; transition: opacity .18s, transform .18s; }
.auth-btn:hover { opacity: .88; transform: translateY(-1px); }
.auth-switch { font-size: 13px; color: var(--text-sub); margin-top: 16px; text-align: center; }
.auth-switch a { color: var(--accent); font-weight: 600; }
.auth-error { background: var(--red-bg); color: var(--red); font-size: 13px; padding: 10px 14px; border-radius: 10px; }

/* Redirect pages for legacy routes */
.redirect-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  padding: 24px;
}

.redirect-card {
  width: 100%;
  max-width: 420px;
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 28px;
  text-align: center;
}

.redirect-logo {
  width: 64px;
  height: 64px;
  object-fit: contain;
  margin-bottom: 12px;
}

.redirect-title { font-size: 22px; font-weight: 800; margin-bottom: 4px; }
.redirect-text { font-size: 14px; color: var(--text-sub); }

/* Tabs */
.tabs { display: flex; gap: 4px; background: var(--card2); border-radius: 10px; padding: 4px; margin-bottom: 16px; }
.tab-btn { flex: 1; padding: 8px; border: none; border-radius: 8px; background: none; font-size: 13px; font-weight: 500; color: var(--text-sub); cursor: pointer; transition: all .15s; }
.tab-btn.active { background: var(--card); color: var(--text); font-weight: 700; box-shadow: 0 1px 6px rgba(0,0,0,.08); }

.page-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.page-grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }

.empty { text-align: center; padding: 32px; color: var(--text-sub); font-size: 14px; }
.mt4 { margin-top: 4px; } .mt8 { margin-top: 8px; } .mt16 { margin-top: 16px; }
.flex-center { display: flex; align-items: center; gap: 8px; }
.tag { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 6px; }
.tag-upi { background: #ede9ff; color: #5f3dc4; }
.tag-bank { background: #dbeafe; color: #1d4ed8; }
body.dark .tag-upi { background: #2a1f50; color: #9b6bff; }
body.dark .tag-bank { background: #1e3050; color: #60a5fa; }
.audit-latest { font-size: 14px; font-weight: 600; margin-top: 6px; }
.audit-reference { margin-top: 4px; font-size: 11px; color: var(--text-sub); }

/* Dashboard refresh style */
.topbar {
  height: 76px;
  padding: 0 24px;
  background: rgba(10, 10, 18, 0.78);
  backdrop-filter: blur(10px);
}

.topbar-left { min-width: 260px; }
.topbar-title { font-size: 30px; font-weight: 800; letter-spacing: -.3px; }
.topbar-sub { margin-top: 2px; font-size: 14px; }

.topbar-search-wrap {
  display: flex; align-items: center; gap: 10px;
  min-width: 360px;
  background: var(--card2);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 10px 12px;
}

.search-icon { color: var(--text-sub); font-size: 15px; }
.topbar-search {
  flex: 1; border: none; outline: none;
  background: transparent; color: var(--text);
  font-size: 13px;
}

.dashboard-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: 16px;
}

.dashboard-main-col,
.dashboard-side-col { min-width: 0; }

.dashboard-hero-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}

.hero-balance-card,
.mini-kpi-card,
.chart-card,
.side-accounts-panel,
.side-note-panel {
  background: linear-gradient(180deg, rgba(255,255,255,.02), rgba(255,255,255,0));
  border: 1px solid var(--border);
  border-radius: 18px;
  box-shadow: 0 10px 28px rgba(0,0,0,.28);
}

.hero-balance-card {
  padding: 18px 20px;
  border-color: rgba(124,92,252,.45);
}

.hero-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.hero-chip {
  font-size: 11px;
  color: #8f7fff;
  background: rgba(124,92,252,.15);
  border: 1px solid rgba(124,92,252,.35);
  border-radius: 999px;
  padding: 4px 10px;
}

.hero-balance { font-size: 38px; font-weight: 800; letter-spacing: -.6px; margin-bottom: 4px; }
.hero-sub { color: var(--text-sub); font-size: 13px; margin-bottom: 8px; }

.mini-kpi-wrap {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.mini-kpi-card { padding: 14px 16px; }
.mini-kpi-value { font-size: 28px; font-weight: 800; margin: 2px 0 6px; }

.quick-actions-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.quick-action {
  border: 1px solid var(--border);
  background: var(--card2);
  color: var(--text);
  border-radius: 12px;
  padding: 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all .15s;
}

.quick-action:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.dashboard-side-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.side-accounts-panel,
.side-note-panel { padding: 18px; }

.side-note-sub { color: var(--text-sub); font-size: 13px; }

.compact-table th,
.compact-table td { padding: 8px 10px; }

.dashboard-account-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card2);
  margin-bottom: 8px;
}

.dashboard-account-bank { font-size: 13px; font-weight: 600; }
.dashboard-account-num { font-size: 11px; color: var(--text-sub); }
.dashboard-account-bal { font-size: 14px; font-weight: 700; color: #9a84ff; }

.side-note-ok {
  margin: 10px 0 6px;
  display: inline-flex;
  background: rgba(34,197,94,.16);
  border: 1px solid rgba(34,197,94,.4);
  color: #4ade80;
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 700;
}

.chart-grid { margin-bottom: 16px; }

@media (max-width: 1200px) {
  .dashboard-shell { grid-template-columns: 1fr; }
  .dashboard-side-col { order: -1; }
}

@media (max-width: 900px) {
  .topbar { height: auto; flex-wrap: wrap; padding: 12px 16px; gap: 10px; }
  .topbar-search-wrap { min-width: 100%; }
  .dashboard-hero-grid { grid-template-columns: 1fr; }
}

::-webkit-scrollbar { width: 5px; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 10px; }


@media (max-width: 900px) {
  .auth-split { grid-template-columns: 1fr; }
  .auth-left { display: none; }
  .chart-grid, .page-grid-2, .page-grid-3, .form-grid { grid-template-columns: 1fr; }
}

/* ─── Variables ───────────────────────────────────────────────────── */
:root {
  --bg: #f0f2f9;
  --sidebar-bg: #ffffff;
  --card: #ffffff;
  --card2: #f7f8fd;
  --text: #1a1a2e;
  --text-sub: #6b6f8a;
  --border: #e2e5f0;
  --accent: #5f3dc4;
  --accent-light: #ede9ff;
  --accent2: #3b82f6;
  --green: #22c55e;
  --green-bg: #dcfce7;
  --red: #ef4444;
  --red-bg: #fee2e2;
  --shadow: 0 2px 16px rgba(60,60,100,.08);
  --shadow-lg: 0 8px 32px rgba(60,60,100,.14);
  --radius: 14px;
  --sidebar-w: 230px;
}

body.dark {
  --bg: #080810;
  --sidebar-bg: #0e0e1c;
  --card: #12121e;
  --card2: #1a1a2c;
  --text: #eeeeff;
  --text-sub: #8888aa;
  --border: #1e1e34;
  --accent: #7c5cfc;
  --accent-light: #2a1f50;
  --accent2: #4f8cff;
  --green: #22c55e;
  --green-bg: #0e2e1c;
  --red: #f87171;
  --red-bg: #2e0e0e;
  --shadow: 0 2px 16px rgba(0,0,0,.35);
  --shadow-lg: 0 8px 40px rgba(0,0,0,.5);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg);
  color: var(--text);
  transition: background .25s, color .25s;
}

a { text-decoration: none; color: inherit; }

.app-shell { display: flex; min-height: 100vh; }

/* Sidebar */
.sidebar {
  width: var(--sidebar-w); flex-shrink: 0;
  background: var(--sidebar-bg);
  border-right: 1px solid var(--border);
  display: flex; flex-direction: column;
  padding: 24px 0 16px;
  position: fixed; top: 0; left: 0; height: 100vh; z-index: 100;
  transition: background .25s, border-color .25s;
}

.sidebar-logo {
  display: flex; align-items: center; gap: 10px;
  padding: 0 20px 24px; border-bottom: 1px solid var(--border);
}

.logo-image { width: 34px; height: 34px; object-fit: contain; border-radius: 8px; flex-shrink: 0; }

.logo-text { font-size: 18px; font-weight: 700; }
.logo-tag { font-size: 10px; color: var(--text-sub); }

.sidebar-nav { flex: 1; padding: 16px 12px; display: flex; flex-direction: column; gap: 4px; }
.nav-section-label { font-size: 10px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--text-sub); padding: 12px 8px 4px; }

.nav-item {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 10px;
  font-size: 14px; font-weight: 500; cursor: pointer;
  color: var(--text-sub); transition: all .18s;
  border: none; background: none; width: 100%; text-align: left;
}

.nav-item:hover { background: var(--accent-light); color: var(--accent); }
.nav-item.active { background: var(--accent-light); color: var(--accent); font-weight: 600; }
.nav-item .icon { font-size: 16px; width: 20px; text-align: center; }

.sidebar-bottom { padding: 12px 20px; border-top: 1px solid var(--border); }

.sidebar-user { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }

.sidebar-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-weight: 700; font-size: 14px; flex-shrink: 0;
}

.sidebar-user-info { flex: 1; overflow: hidden; }
.sidebar-user-name { font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sidebar-user-email { font-size: 11px; color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.theme-toggle-row { display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--text-sub); padding: 4px 0; }

.toggle-switch {
  width: 42px; height: 24px; background: var(--border);
  border-radius: 12px; position: relative; cursor: pointer;
  transition: background .2s; border: none;
}

.toggle-switch.on { background: var(--accent); }
.toggle-knob { width: 18px; height: 18px; background: #fff; border-radius: 50%; position: absolute; top: 3px; left: 3px; transition: left .2s; }
.toggle-switch.on .toggle-knob { left: 21px; }

/* Main */
.main { margin-left: var(--sidebar-w); flex: 1; display: flex; flex-direction: column; min-height: 100vh; }

/* Topbar */
.topbar {
  height: 64px; display: flex; align-items: center; gap: 12px;
  padding: 0 28px; background: var(--card);
  border-bottom: 1px solid var(--border);
  position: sticky; top: 0; z-index: 90;
  transition: background .25s, border-color .25s;
}

.topbar-title { font-size: 20px; font-weight: 700; }
.topbar-sub { font-size: 13px; color: var(--text-sub); }
.spacer { flex: 1; }

.balance-chip {
  display: flex; align-items: center; gap: 10px;
  background: var(--card2); border: 1px solid var(--border);
  border-radius: 12px; padding: 8px 16px;
}

.balance-chip .label { color: var(--text-sub); font-weight: 400; font-size: 12px; }
.balance-chip .amount { font-size: 16px; font-weight: 700; }

.topbar-actions { display: flex; gap: 8px; }

.btn { border: none; border-radius: 10px; cursor: pointer; font-weight: 600; transition: all .18s; display: inline-flex; align-items: center; gap: 6px; font-size: 13px; }
.btn-primary { background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; padding: 9px 18px; }
.btn-primary:hover { opacity: .88; transform: translateY(-1px); }
.btn-secondary { background: var(--card2); border: 1px solid var(--border); color: var(--text); padding: 9px 14px; }
.btn-secondary:hover { background: var(--accent-light); color: var(--accent); border-color: var(--accent); }
.btn-icon { width: 38px; height: 38px; padding: 0; justify-content: center; }
.btn-danger { background: var(--red-bg); color: var(--red); border: 1px solid transparent; padding: 7px 12px; font-size: 12px; border-radius: 8px; }
.btn-danger:hover { border-color: var(--red); }
.btn-logout { background: none; border: 1px solid var(--border); color: var(--text-sub); padding: 8px 14px; border-radius: 8px; font-size: 13px; cursor: pointer; font-weight: 500; }
.btn-logout:hover { border-color: var(--red); color: var(--red); }

/* Pages */
.page { padding: 24px 28px; display: none; }
.page.active { display: block; }

.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.section-title { font-size: 16px; font-weight: 700; }

/* KPI Grid */
.kpi-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; margin-bottom: 20px; }

.kpi-card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  box-shadow: var(--shadow); transition: background .25s, border-color .25s;
}

.kpi-label { font-size: 13px; color: var(--text-sub); margin-bottom: 8px; }
.kpi-value { font-size: 26px; font-weight: 800; letter-spacing: -.5px; }
.kpi-badge { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 600; padding: 3px 8px; border-radius: 20px; margin-top: 8px; }
.kpi-badge.up { background: var(--green-bg); color: var(--green); }
.kpi-badge.down { background: var(--red-bg); color: var(--red); }
.kpi-badge.neutral { background: var(--accent-light); color: var(--accent); }

/* Charts */
.chart-grid { display: grid; grid-template-columns: 1.6fr 1fr; gap: 16px; margin-bottom: 20px; }

.chart-card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  box-shadow: var(--shadow); transition: background .25s, border-color .25s;
}

.chart-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 16px; }
.chart-title { font-size: 14px; font-weight: 700; }
.chart-meta { font-size: 12px; color: var(--text-sub); }
.chart-amount { font-size: 22px; font-weight: 800; margin-bottom: 2px; }
.chart-delta { font-size: 12px; color: var(--green); font-weight: 600; }

/* Dist bar */
.dist-bar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; margin: 12px 0 16px; gap: 2px; }
.dist-seg { border-radius: 4px; }
.dist-list { display: flex; flex-direction: column; gap: 8px; }
.dist-item { display: flex; align-items: center; gap: 8px; font-size: 13px; }
.dist-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.dist-label { flex: 1; color: var(--text-sub); }
.dist-val { font-weight: 600; }
.dist-pct { font-size: 12px; color: var(--text-sub); margin-left: 4px; }

/* Forms */
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.form-grid.cols-1 { grid-template-columns: 1fr; }

.form-group { display: flex; flex-direction: column; gap: 6px; }
.form-label { font-size: 12px; font-weight: 600; color: var(--text-sub); }

.form-input, .form-select {
  padding: 11px 14px; border-radius: 10px;
  border: 1.5px solid var(--border);
  background: var(--card2); color: var(--text);
  font-size: 14px; width: 100%;
  transition: border .15s, background .25s; outline: none;
}

.form-input:focus, .form-select:focus { border-color: var(--accent); background: var(--card); }
.form-input::placeholder { color: var(--text-sub); }
.form-section-title { font-size: 12px; font-weight: 700; color: var(--text-sub); margin: 14px 0 4px; padding-bottom: 6px; border-bottom: 1px solid var(--border); grid-column: 1 / -1; text-transform: uppercase; letter-spacing: .05em; }

/* Panels */
.panel {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 20px;
  box-shadow: var(--shadow); margin-bottom: 16px;
  transition: background .25s, border-color .25s;
}

.panel-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.panel-title { font-size: 15px; font-weight: 700; }

/* Account chip */
.account-chip {
  display: flex; align-items: center; gap: 12px;
  background: var(--card2); border: 1.5px solid var(--border);
  border-radius: 12px; padding: 14px 16px; margin-bottom: 10px;
  transition: border-color .15s;
}

.account-chip:hover { border-color: var(--accent); }
.account-chip-icon { width: 38px; height: 38px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 18px; background: var(--accent-light); }
.account-chip-info { flex: 1; }
.account-chip-bank { font-size: 14px; font-weight: 600; }
.account-chip-num { font-size: 12px; color: var(--text-sub); }
.account-chip-bal { font-weight: 700; font-size: 14px; }

/* Table */
.data-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.data-table th { text-align: left; padding: 10px 14px; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; color: var(--text-sub); border-bottom: 1px solid var(--border); }
.data-table td { padding: 12px 14px; border-bottom: 1px solid var(--border); }
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--card2); }

/* Status badge */
.status-badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 700; }
.status-badge::before { content: ''; width: 6px; height: 6px; border-radius: 50%; display: inline-block; }
.status-badge.COMPLETED { background: var(--green-bg); color: var(--green); }
.status-badge.COMPLETED::before { background: var(--green); }
.status-badge.FAILED { background: var(--red-bg); color: var(--red); }
.status-badge.FAILED::before { background: var(--red); }
.status-badge.CREATED, .status-badge.VALIDATED, .status-badge.SENT { background: var(--accent-light); color: var(--accent); }
.status-badge.CREATED::before, .status-badge.VALIDATED::before, .status-badge.SENT::before { background: var(--accent); }

/* Timeline */
.timeline { display: flex; flex-direction: column; }
.timeline-item { display: flex; gap: 14px; padding-bottom: 20px; position: relative; }
.timeline-item:last-child { padding-bottom: 0; }
.timeline-item:not(:last-child)::after { content: ''; position: absolute; left: 15px; top: 32px; width: 2px; bottom: 0; background: var(--border); }
.timeline-dot { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; flex-shrink: 0; z-index: 1; }
.timeline-dot.COMPLETED { background: var(--green-bg); color: var(--green); }
.timeline-dot.FAILED { background: var(--red-bg); color: var(--red); }
.timeline-dot.CREATED, .timeline-dot.VALIDATED, .timeline-dot.SENT { background: var(--accent-light); color: var(--accent); }
.timeline-content { flex: 1; padding-top: 5px; }
.timeline-label { font-size: 13px; font-weight: 600; }
.timeline-time { font-size: 11px; color: var(--text-sub); }
.timeline-note { font-size: 12px; color: var(--text-sub); margin-top: 2px; }

/* Beneficiary */
.bene-card { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-radius: 12px; background: var(--card2); border: 1px solid var(--border); margin-bottom: 8px; }
.bene-avatar { width: 36px; height: 36px; border-radius: 50%; background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 14px; flex-shrink: 0; }
.bene-info { flex: 1; }
.bene-name { font-size: 14px; font-weight: 600; }
.bene-num { font-size: 12px; color: var(--text-sub); }

/* Verify */
.verify-result { padding: 10px 14px; border-radius: 10px; font-size: 13px; margin-top: 8px; font-weight: 500; display: none; }
.verify-result.show-ok { background: var(--green-bg); color: var(--green); display: block; }
.verify-result.show-info { background: var(--accent-light); color: var(--accent); display: block; }
.verify-result.show-err { background: var(--red-bg); color: var(--red); display: block; }

/* Auth */
.auth-page { min-height: 100vh; display: flex; align-items: center; justify-content: center; background: var(--bg); padding: 24px; }

.auth-split { display: grid; grid-template-columns: 1.2fr 1fr; max-width: 940px; width: 100%; border-radius: 20px; overflow: hidden; box-shadow: var(--shadow-lg); min-height: 580px; }

.auth-left { background: linear-gradient(160deg, #3b1fc7 0%, #0f0630 50%, #1d4ed8 100%); padding: 48px 40px; display: flex; flex-direction: column; justify-content: space-between; color: #fff; }
.auth-brand { font-size: 24px; font-weight: 800; margin-bottom: 4px; }
.auth-tagline { font-size: 13px; opacity: .7; margin-bottom: 40px; }
.auth-feature-list { display: flex; flex-direction: column; gap: 16px; }
.auth-feature { display: flex; gap: 12px; align-items: flex-start; }
.auth-feature-icon { width: 36px; height: 36px; background: rgba(255,255,255,.15); border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
.auth-feature-text h4 { font-size: 14px; font-weight: 600; margin-bottom: 2px; }
.auth-feature-text p { font-size: 12px; opacity: .7; }

.auth-right { background: var(--card); padding: 48px 40px; display: flex; flex-direction: column; justify-content: center; }
.auth-title { font-size: 22px; font-weight: 800; margin-bottom: 6px; }
.auth-subtitle { font-size: 14px; color: var(--text-sub); margin-bottom: 28px; }
.auth-form { display: flex; flex-direction: column; gap: 14px; }
.auth-btn { padding: 13px; border-radius: 12px; border: none; background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; font-size: 15px; font-weight: 700; cursor: pointer; transition: opacity .18s, transform .18s; }
.auth-btn:hover { opacity: .88; transform: translateY(-1px); }
.auth-switch { font-size: 13px; color: var(--text-sub); margin-top: 16px; text-align: center; }
.auth-switch a { color: var(--accent); font-weight: 600; }
.auth-error { background: var(--red-bg); color: var(--red); font-size: 13px; padding: 10px 14px; border-radius: 10px; }

/* Redirect pages for legacy routes */
.redirect-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  padding: 24px;
}

.redirect-card {
  width: 100%;
  max-width: 420px;
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 28px;
  text-align: center;
}

.redirect-logo {
  width: 64px;
  height: 64px;
  object-fit: contain;
  margin-bottom: 12px;
}

.redirect-title { font-size: 22px; font-weight: 800; margin-bottom: 4px; }
.redirect-text { font-size: 14px; color: var(--text-sub); }

/* Tabs */
.tabs { display: flex; gap: 4px; background: var(--card2); border-radius: 10px; padding: 4px; margin-bottom: 16px; }
.tab-btn { flex: 1; padding: 8px; border: none; border-radius: 8px; background: none; font-size: 13px; font-weight: 500; color: var(--text-sub); cursor: pointer; transition: all .15s; }
.tab-btn.active { background: var(--card); color: var(--text); font-weight: 700; box-shadow: 0 1px 6px rgba(0,0,0,.08); }

.page-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.page-grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }

.empty { text-align: center; padding: 32px; color: var(--text-sub); font-size: 14px; }
.mt4 { margin-top: 4px; } .mt8 { margin-top: 8px; } .mt16 { margin-top: 16px; }
.flex-center { display: flex; align-items: center; gap: 8px; }
.tag { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 6px; }
.tag-upi { background: #ede9ff; color: #5f3dc4; }
.tag-bank { background: #dbeafe; color: #1d4ed8; }
body.dark .tag-upi { background: #2a1f50; color: #9b6bff; }
body.dark .tag-bank { background: #1e3050; color: #60a5fa; }
.audit-latest { font-size: 14px; font-weight: 600; margin-top: 6px; }
.audit-reference { margin-top: 4px; font-size: 11px; color: var(--text-sub); }

/* Dashboard refresh style */
.topbar {
  height: 76px;
  padding: 0 24px;
  background: rgba(10, 10, 18, 0.78);
  backdrop-filter: blur(10px);
}

.topbar-left { min-width: 260px; }
.topbar-title { font-size: 30px; font-weight: 800; letter-spacing: -.3px; }
.topbar-sub { margin-top: 2px; font-size: 14px; }

.topbar-search-wrap {
  display: flex; align-items: center; gap: 10px;
  min-width: 360px;
  background: var(--card2);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 10px 12px;
}

.search-icon { color: var(--text-sub); font-size: 15px; }
.topbar-search {
  flex: 1; border: none; outline: none;
  background: transparent; color: var(--text);
  font-size: 13px;
}

.topbar-search-wrap.search-active {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(124, 92, 252, 0.15);
}

.dashboard-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: 16px;
}

.dashboard-main-col,
.dashboard-side-col { min-width: 0; }

.dashboard-hero-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}

.hero-balance-card,
.mini-kpi-card,
.chart-card,
.side-accounts-panel,
.side-note-panel {
  background: linear-gradient(180deg, rgba(255,255,255,.02), rgba(255,255,255,0));
  border: 1px solid var(--border);
  border-radius: 18px;
  box-shadow: 0 10px 28px rgba(0,0,0,.28);
}

.hero-balance-card {
  padding: 18px 20px;
  border-color: rgba(124,92,252,.45);
}

.hero-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.hero-chip {
  font-size: 11px;
  color: #8f7fff;
  background: rgba(124,92,252,.15);
  border: 1px solid rgba(124,92,252,.35);
  border-radius: 999px;
  padding: 4px 10px;
}

.hero-balance { font-size: 38px; font-weight: 800; letter-spacing: -.6px; margin-bottom: 4px; }
.hero-sub { color: var(--text-sub); font-size: 13px; margin-bottom: 8px; }

.mini-kpi-wrap {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.mini-kpi-card { padding: 14px 16px; }
.mini-kpi-value { font-size: 28px; font-weight: 800; margin: 2px 0 6px; }

.quick-actions-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.quick-action {
  border: 1px solid var(--border);
  background: var(--card2);
  color: var(--text);
  border-radius: 12px;
  padding: 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all .15s;
}

.quick-action:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.dashboard-side-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.side-accounts-panel,
.side-note-panel { padding: 18px; }

.side-note-sub { color: var(--text-sub); font-size: 13px; }

.compact-table th,
.compact-table td { padding: 8px 10px; }

.dashboard-account-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card2);
  margin-bottom: 8px;
}

.dashboard-account-bank { font-size: 13px; font-weight: 600; }
.dashboard-account-num { font-size: 11px; color: var(--text-sub); }
.dashboard-account-bal { font-size: 14px; font-weight: 700; color: #9a84ff; }

.side-note-ok {
  margin: 10px 0 6px;
  display: inline-flex;
  background: rgba(34,197,94,.16);
  border: 1px solid rgba(34,197,94,.4);
  color: #4ade80;
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 700;
}

.chart-grid { margin-bottom: 16px; }

@media (max-width: 1200px) {
  .dashboard-shell { grid-template-columns: 1fr; }
  .dashboard-side-col { order: -1; }
}

@media (max-width: 900px) {
  .topbar { height: auto; flex-wrap: wrap; padding: 12px 16px; gap: 10px; }
  .topbar-search-wrap { min-width: 100%; }
  .dashboard-hero-grid { grid-template-columns: 1fr; }
}

::-webkit-scrollbar { width: 5px; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 10px; }


@media (max-width: 900px) {
  .auth-split { grid-template-columns: 1fr; }
